// ==============================================================================
// SELETTORE ASSISTITI STILE WHATSAPP CANALI (RICERCA & FILTRI ISTANTANEI)
// ==============================================================================
var _filtroCategoriaWhatsAppAttivo = 'tutti';
var _filtroTestoWhatsAppAttivo = '';

function filtraPazientiWhatsApp(query) {
  _filtroTestoWhatsAppAttivo = (query || '').trim().toLowerCase();
  applicaFiltriWhatsAppDOM();
}
window.filtraPazientiWhatsApp = filtraPazientiWhatsApp;

function filtraCategoriaWhatsApp(cat, btn) {
  _filtroCategoriaWhatsAppAttivo = cat;
  document.querySelectorAll('.wa-filter-pill').forEach(function (b) { b.classList.remove('active'); });
  if (btn) btn.classList.add('active');
  applicaFiltriWhatsAppDOM();
}
window.filtraCategoriaWhatsApp = filtraCategoriaWhatsApp;

function applicaFiltriWhatsAppDOM() {
  var rows = document.querySelectorAll('#lista-switch-pazienti-rapido .whatsapp-pz-item');
  var matchCount = 0;
  rows.forEach(function (row) {
    var nome = (row.getAttribute('data-nome') || '').toLowerCase();
    var pat = (row.getAttribute('data-patologia') || '').toLowerCase();
    var allettato = row.getAttribute('data-allettato') === 'true';
    var terapieOggi = parseInt(row.getAttribute('data-terapie-oggi') || '0', 10);
    var ritardi = parseInt(row.getAttribute('data-ritardi') || '0', 10);

    var matchText = !_filtroTestoWhatsAppAttivo || nome.includes(_filtroTestoWhatsAppAttivo) || pat.includes(_filtroTestoWhatsAppAttivo);
    var matchCat = true;
    if (_filtroCategoriaWhatsAppAttivo === 'terapie') matchCat = terapieOggi > 0;
    else if (_filtroCategoriaWhatsAppAttivo === 'ritardi') matchCat = ritardi > 0;
    else if (_filtroCategoriaWhatsAppAttivo === 'allettati') matchCat = allettato;

    if (matchText && matchCat) {
      row.style.display = 'flex';
      matchCount++;
    } else {
      row.style.display = 'none';
    }
  });

  var noRes = document.getElementById('wa-no-results-msg');
  if (matchCount === 0) {
    if (!noRes) {
      var nr = document.createElement('div');
      nr.id = 'wa-no-results-msg';
      nr.style.cssText = 'padding:24px 16px; text-align:center; color:#64748b; font-size:13px; font-weight:700;';
      nr.innerHTML = 'Nessun assistito corrisponde ai filtri selezionati.';
      var c = document.getElementById('lista-switch-pazienti-rapido');
      if (c) c.appendChild(nr);
    }
  } else if (noRes) {
    noRes.remove();
  }
}
window.applicaFiltriWhatsAppDOM = applicaFiltriWhatsAppDOM;


// ==============================================================================
// MOTORE VOCALE NATURALE HD CAREASSIST (Azure Neural HD + Pause Naturali)
// ==============================================================================
let _audioElementCareAssistAttivo = null;

function fermaVoceHDGlobale() {
  if (_audioElementCareAssistAttivo) {
    try {
      _audioElementCareAssistAttivo.pause();
      _audioElementCareAssistAttivo.currentTime = 0;
    } catch (e) { }
    _audioElementCareAssistAttivo = null;
  }
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch (e) { }
  }
}
window.fermaVoceHDGlobale = fermaVoceHDGlobale;
window.fermaVoceSintesiInApp = fermaVoceHDGlobale;

function riproduciVoceNaturaleHD(testo, onEndCallback) {
  fermaVoceHDGlobale();
  if (!testo || typeof testo !== 'string') return;

  // Sanificazione accurata del testo: espansioni fonetiche e pause naturali
  let t = (testo || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, ' e ')
    .replace(/&/g, ' e ')
    .replace(/[•▪▸►✓✔✕✖★☆✦]/g, ', ')
    .replace(/\bmg\b/gi, 'milligrammi')
    .replace(/\bmcg\b/gi, 'microgrammi')
    .replace(/\bcpr\b/gi, 'compresse')
    .replace(/\bml\b/gi, 'millilitri')
    .replace(/\bgg\b/gi, 'giorni')
    .replace(/\bSGLT2\b/gi, 'S G L T 2')
    .replace(/\bHbA1c\b/gi, 'emoglobina glicata')
    .replace(/\bUI\b/gi, 'unità internazionali')
    .replace(/\b112\b/g, 'uno uno due')
    .replace(/\bNUE\b/gi, 'Numero Unico Europeo')
    .replace(/\s*\/\s*/g, ' oppure ')
    .replace(/\s*-\s*/g, ' - ')
    .replace(/\.{2,}/g, '. ')
    .replace(/:\s*/g, ': ')
    .replace(/\s+/g, ' ')
    .trim();

  // Determina base URL assoluta corretta (se siamo in locale o cloud)
  var ttsBase = '';
  try {
    if (typeof getCareAssistSyncBase === 'function') ttsBase = getCareAssistSyncBase();
  } catch(e) {}
  const apiUrl = (ttsBase ? ttsBase : '') + '/api/tts-umano?voice=elsa&text=' + encodeURIComponent(t);

  // Stop rigido a qualsiasi sintesi vocale prima di iniziare
  if ('speechSynthesis' in window) {
    try { window.speechSynthesis.cancel(); } catch(e) {}
  }

  const audio = new Audio(apiUrl);
  _audioElementCareAssistAttivo = audio;

  let isAudioStarted = false;

  audio.onplay = function () {
    isAudioStarted = true;
    // Assicurati che WebSpeech sia spento
    if ('speechSynthesis' in window) {
      try { window.speechSynthesis.cancel(); } catch(e) {}
    }
  };

  audio.onended = function () {
    _audioElementCareAssistAttivo = null;
    if (typeof onEndCallback === 'function') onEndCallback();
  };

  audio.onerror = function (e) {
    console.warn('Errore caricamento audio MP3 Elsa:', e);
    _audioElementCareAssistAttivo = null;
    // Attiva il fallback locale SOLO ED ESCLUSIVAMENTE se l\'audio naturale non è partito
    if (!isAudioStarted && typeof parlaFallbackBrowserCareAssist === 'function') {
      parlaFallbackBrowserCareAssist(t);
    }
    if (typeof onEndCallback === 'function') onEndCallback();
  };

  audio.play().then(function() {
    isAudioStarted = true;
  }).catch(function (err) {
    console.warn('Riproduzione audio MP3 bloccata da browser o fallita:', err);
    // SOLO se non è partito l\'audio naturale e c\'è stato un blocco effettivo
    if (!isAudioStarted && typeof parlaFallbackBrowserCareAssist === 'function') {
      parlaFallbackBrowserCareAssist(t);
    }
  });
}
window.riproduciVoceNaturaleHD = riproduciVoceNaturaleHD;


// ==============================================================
// MOTORE CLINICO AUTOMATICO FARMACO MULTI-TEMPO & SCORTA CONDIVISA
// ==============================================================
function getNomeBaseFarmaco(t) {
  if (!t || !t.farmaco) return '';
  return (t.farmaco || '')
    .replace(/\s*\(\d+ª?\s*dose[^)]*\)/gi, '')
    .replace(/\s*\(tempo\s*\d+[^)]*\)/gi, '')
    .trim().toLowerCase();
}

function getDatiFarmacoMultiTempo(t, tutteTerapie) {
  if (!t) return null;
  var terapie = tutteTerapie;
  if (!terapie) {
    var p = (typeof getActivePaziente === 'function') ? getActivePaziente() : null;
    terapie = p ? (p.terapie || []) : [];
  }

  var cleanNome = getNomeBaseFarmaco(t);
  if (!cleanNome || cleanNome.length < 2) return null;

  var gemelle = terapie.filter(function (item) {
    if (t.gruppoFarmacoId && item.gruppoFarmacoId) {
      return item.gruppoFarmacoId === t.gruppoFarmacoId;
    }
    var itemClean = getNomeBaseFarmaco(item);
    return itemClean === cleanNome || cleanNome.indexOf(itemClean) >= 0 || itemClean.indexOf(cleanNome) >= 0;
  });

  if (gemelle.length <= 1) return null;

  // Ordina cronologicamente
  if (typeof comparaOrariTerapie === 'function') {
    gemelle.sort(comparaOrariTerapie);
  }

  var consumoTotaleDie = 0;
  gemelle.forEach(function (item) {
    var q = parseFloat(item.quantitaQuota);
    if (isNaN(q) || q <= 0) {
      var m = (item.dosaggio || item.farmaco || '').match(/(\d+(?:[.,]\d+)?)\s*(?:cpr|compresse)/i);
      q = m ? parseFloat(m[1].replace(',', '.')) : 1.0;
    }
    consumoTotaleDie += q;
  });

  // La scorta reale a casa è condivisa (prendi il valore della terapia corrente)
  var scorta = parseFloat(t.scorta) || 0;
  var giorniAutonomia = (consumoTotaleDie > 0 && scorta > 0) ? Math.floor(scorta / consumoTotaleDie) : 0;

  var dTermine = new Date();
  dTermine.setDate(dTermine.getDate() + giorniAutonomia);
  var dataTermineStr = (giorniAutonomia > 0) ? dTermine.toLocaleDateString('it-IT') : 'Esaurito';

  var indiceTempo = gemelle.findIndex(function (item) { return item.id === t.id; }) + 1;
  var orariStr = gemelle.map(function (item) { return item.ora; }).join(' e ');

  return {
    numTempi: gemelle.length,
    indiceTempo: indiceTempo > 0 ? indiceTempo : 1,
    consumoTotaleDie: consumoTotaleDie,
    scortaCondivisa: scorta,
    giorniAutonomia: giorniAutonomia,
    dataTermineStr: dataTermineStr,
    orariStr: orariStr,
    gemelle: gemelle
  };
}


// ==========================================
// MOTORE CLINICO AUTOMATICO PENNE & INSULINA
// ==========================================
function isFarmacoPennaIniettabile(t) {
  if (!t) return false;
  // Se l'utente ha esplicitamente marcato o il tipo è compressa/capsula/gocce, non è MAI una penna
  if (t.tipoFormulazione === 'compressa' || t.tipoFormulazione === 'capsula' || t.tipoFormulazione === 'gocce') return false;
  if (t.tipoFormulazione === 'penna') return true;

  // Antidiabetici ORALI noti: non sono MAI penne (evita falsi positivi es. DIAMICRON con dosaggio sporcato)
  var oraliNoti = ['diamicron', 'gliclazide', 'metformina', 'glucophage', 'metforal', 'rybelsus', 'jardiance', 'empagliflozin', 'forxiga', 'dapagliflozin', 'januvia', 'sitagliptin', 'trajenta', 'linagliptin', 'eucreas', 'janumet', 'amaryl', 'glimepiride', 'galvus', 'vildagliptin', 'xigduo', 'synjardy'];
  var nomeLow = ((t.farmaco || '') + ' ' + (t.principio || '')).toLowerCase();
  for (var k = 0; k < oraliNoti.length; k++) {
    if (nomeLow.indexOf(oraliNoti[k]) >= 0) return false;
  }

  // Analisi clinica SOLO su nome farmaco e principio attivo (MAI sulle istruzioni/modo per evitare falsi positivi)
  var fStr = (t.farmaco || '').toLowerCase();
  var pStr = (t.principio || '').toLowerCase();
  var dStr = (t.dosaggio || '').toLowerCase();

  // Se contiene esplicitamente penna o iniezione
  if (fStr.indexOf('penna') >= 0 || fStr.indexOf('pen\b') >= 0 || fStr.indexOf('multidose') >= 0 || dStr.indexOf('sottocute') >= 0) {
    return true;
  }

  // Nomi commerciali noti di penne iniettabili per diabete / dimagrimento
  var penBrands = [
    'xultophy', 'tresiba', 'lantus', 'toujeo', 'novorapid', 'humalog',
    'fiasp', 'ozempic', 'victoza', 'trulicity', 'mounjaro', 'saxenda',
    'soliqua', 'suliqua', 'byetta', 'levemir', 'insulatard', 'actrapid',
    'apidra', 'lyumjev', 'ryzodeg'
  ];
  for (var i = 0; i < penBrands.length; i++) {
    if (fStr.indexOf(penBrands[i]) >= 0) return true;
  }

  // Principi attivi noti di insuline e analoghi GLP-1 iniettabili (se specificati nel principio o nome)
  var molecole = ['insulina', 'liraglutide', 'semaglutide', 'tirzepatide', 'dulaglutide', 'degludec', 'glargina', 'lispro', 'aspart', 'lixisenatide', 'detemir'];
  for (var j = 0; j < molecole.length; j++) {
    if (fStr.indexOf(molecole[j]) >= 0 || pStr.indexOf(molecole[j]) >= 0) {
      // Se è un farmaco orale noto (es. Rybelsus semaglutide orale), non è penna
      if (fStr.indexOf('rybelsus') >= 0) return false;
      return true;
    }
  }

  return false;
}

function calcolaDatiPennaIniettabile(t) {
  var unitaTotaliPenna = parseInt(t.unitaPerPenna) || 300;
  var doseDie = parseFloat(t.unitaDoseDie);
  if (isNaN(doseDie) || doseDie <= 0) {
    var m = (t.dosaggio || '').match(/(\d+(?:[.,]\d+)?)\s*(?:unità|ui|u\b|scatti)/i);
    if (m) {
      doseDie = parseFloat(m[1].replace(',', '.'));
    } else {
      doseDie = 16;
    }
  }
  var giorniPerPenna = Math.max(1, Math.floor(unitaTotaliPenna / doseDie));
  var penneRaw = (typeof t.penneScorta !== 'undefined') ? parseFloat(t.penneScorta) : (parseFloat(t.scorta) || 2);
  if (isNaN(penneRaw) || penneRaw < 0) penneRaw = 0;

  // Calcolo penne intere in frigo ed eventuale penna attiva in uso
  var penneIntere = Math.floor(penneRaw);
  var frazioneUso = penneRaw - penneIntere;
  var unitaInAttiva = Math.round(frazioneUso * unitaTotaliPenna);
  var unitaTotali = Math.round(penneRaw * unitaTotaliPenna);

  var giorniAutonomia = Math.max(0, Math.floor(penneRaw * giorniPerPenna));

  var dataEsaurimento = new Date();
  dataEsaurimento.setDate(dataEsaurimento.getDate() + giorniAutonomia);
  var dataEsaurimentoStr = dataEsaurimento.toLocaleDateString('it-IT');

  // La ricetta va richiesta quando si apre l'ultima penna in frigorifero
  var pennePrimaDellUltima = Math.max(0, Math.ceil(penneRaw) - 1);
  var giorniAnticipo = Math.max(0, Math.floor(pennePrimaDellUltima * giorniPerPenna));
  var dataRichiestaMMG = new Date();
  dataRichiestaMMG.setDate(dataRichiestaMMG.getDate() + giorniAnticipo);
  var dataRichiestaMMGStr = dataRichiestaMMG.toLocaleDateString('it-IT');

  var richiediSubito = (penneRaw <= 1.05 || giorniAutonomia <= 15);

  return {
    unitaTotaliPenna: unitaTotaliPenna,
    doseDie: doseDie,
    giorniPerPenna: giorniPerPenna,
    penne: penneRaw,
    penneIntere: penneIntere,
    unitaInAttiva: unitaInAttiva,
    unitaTotali: unitaTotali,
    giorniAutonomia: giorniAutonomia,
    dataEsaurimentoStr: dataEsaurimentoStr,
    dataRichiestaMMGStr: dataRichiestaMMGStr,
    richiediSubito: richiediSubito
  };
}

