// Ingrandimento Clinico Centrale ad Alta Leggibilità (Lente HUD al Passaggio Mouse)
// Helper dedicati per Lente Clinica (chiamata pulita senza HTML inline nell'onmouseenter)
function toggleOrariMedicoInline(event) {
  if (event) {
    if (event.stopPropagation) event.stopPropagation();
    if (event.preventDefault) event.preventDefault();
  }
  const box = document.getElementById('box-orari-medico-inline');
  const lbl = document.getElementById('toggle-orari-medico-btn-lbl');
  const arrow = document.getElementById('toggle-orari-medico-arrow');
  if (!box) return;
  if (box.style.display === 'none' || !box.style.display) {
    box.style.display = 'block';
    if (lbl) lbl.textContent = 'Nascondi Orari Settimanali';
    if (arrow) arrow.textContent = '▲';
  } else {
    box.style.display = 'none';
    if (lbl) lbl.textContent = 'Mostra Orari Settimanali Completi';
    if (arrow) arrow.textContent = '▼';
  }
}
window.toggleOrariMedicoInline = toggleOrariMedicoInline;

function mostraLenteMedicoCurante() {
  // Richiesta Dr.ssa Potenza: nessun popup modale invasivo, orari integrati direttamente nella scheda paziente
  toggleOrariMedicoInline();
}
window.mostraLenteMedicoCurante = mostraLenteMedicoCurante;

function mostraLenteFarmacia() {
  // Disattivato popup invasivo su richiesta del medico
  return;
}
window.mostraLenteFarmacia = mostraLenteFarmacia;

let _isOverTrigger = false;
let _isOverOverlay = false;
let _lenteHideTimer = null;
let _currentLenteActionFn = null;

function mostraLenteClinica(titolo, testo, icona = '🩺', actionFn = null, actionLabel = 'Apri Scheda') {
  // Disattivato permanentemente su richiesta del Medico Curante (Dr.ssa Carolina Potenza):
  // Eliminati tutti i popup invasivi che coprono la schermata e la cartella del paziente.
  const overlay = document.getElementById('clinica-lente-overlay');
  if (overlay) {
    overlay.style.display = 'none';
    overlay.style.opacity = '0';
    overlay.style.pointerEvents = 'none';
  }
  return;
}

function eseguiAzioneLenteClinica(event) {
  if (event) {
    if (event.preventDefault) event.preventDefault();
    if (event.stopPropagation) event.stopPropagation();
  }
  nascondiLenteClinica(event, true);
}

function nascondiLenteClinica(event, immediate = false) {
  const overlay = document.getElementById('clinica-lente-overlay');
  if (overlay) {
    overlay.style.display = 'none';
    overlay.style.opacity = '0';
    overlay.style.pointerEvents = 'none';
  }
}

// Chiudi HUD lente al tocco o click all'esterno (senza backdrop bloccante)
document.addEventListener('pointerdown', (e) => {
  const overlay = document.getElementById('clinica-lente-overlay');
  if (!overlay || overlay.style.display === 'none' || overlay.style.opacity === '0') return;
  if (!overlay.contains(e.target) && !e.target.closest('.clinica-zoom-item') && !e.target.closest('.tile')) {
    nascondiLenteClinica(null, true);
  }
});

// Chiudi HUD lente con tasto ESC
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    nascondiLenteClinica(null, true);
  }
});

// Esponi globalmente per gli handler inline HTML
window.mostraLenteClinica = mostraLenteClinica;
window.nascondiLenteClinica = nascondiLenteClinica;
window.eseguiAzioneLenteClinica = eseguiAzioneLenteClinica;

// Finestra di Conferma Personalizzata (Custom Dialog Elegante)
function customConfirm(titolo, testo, icona = '💊', okLabel) {
  return new Promise((resolve) => {
    const modal = document.getElementById('modal-custom-confirm');
    if (!modal) {
      return resolve(window.confirm((titolo ? titolo + '\n\n' : '') + (testo || 'Confermi?')));
    }
    if (modal.parentElement !== document.body) {
      document.body.appendChild(modal);
    }
    const titleEl = document.getElementById('confirm-modal-title');
    const textEl = document.getElementById('confirm-modal-text');
    const iconEl = document.getElementById('confirm-modal-icon');
    const btnOk = document.getElementById('confirm-modal-ok');
    const btnCancel = document.getElementById('confirm-modal-cancel');
    const btnX = document.getElementById('confirm-modal-x-btn');

    if (titleEl) titleEl.textContent = titolo || 'Conferma Azione';
    if (textEl) textEl.textContent = testo || 'Sei sicuro di voler procedere?';
    if (iconEl) iconEl.textContent = icona || '💊';
    if (btnOk) btnOk.textContent = okLabel || 'Conferma';

    modal.style.zIndex = '999999999';
    modal.classList.add('active');
    modal.style.display = 'flex';

    let resolved = false;

    const cleanup = () => {
      modal.classList.remove('active');
      modal.style.display = 'none';
      if (btnOk) btnOk.removeEventListener('click', handleOk);
      if (btnCancel) btnCancel.removeEventListener('click', handleCancel);
      if (btnX) btnX.removeEventListener('click', handleCancel);
      modal.removeEventListener('click', handleBackdrop);
      window.removeEventListener('keydown', handleKey);
    };

    const handleOk = (ev) => {
      if (ev) ev.stopPropagation();
      if (resolved) return;
      resolved = true;
      cleanup();
      resolve(true);
    };

    const handleCancel = (ev) => {
      if (ev) ev.stopPropagation();
      if (resolved) return;
      resolved = true;
      cleanup();
      resolve(false);
    };

    const handleBackdrop = (ev) => {
      if (ev.target === modal) {
        if (resolved) return;
        resolved = true;
        cleanup();
        resolve(false);
      }
    };

    const handleKey = (ev) => {
      if (ev.key === 'Escape') {
        if (resolved) return;
        resolved = true;
        cleanup();
        resolve(false);
      }
    };

    if (btnOk) btnOk.addEventListener('click', handleOk);
    if (btnCancel) btnCancel.addEventListener('click', handleCancel);
    if (btnX) btnX.addEventListener('click', handleCancel);
    modal.addEventListener('click', handleBackdrop);
    window.addEventListener('keydown', handleKey);
  });
}

// ==========================================================================
// CESTINO & RIPRISTINO: ogni cancellazione finisce qui e resta recuperabile per 60 giorni
// (terapie, visite, ausili, annotazioni del diario, registrazioni glicemiche, cartelle assistito)
// Il Cestino è dentro AppData._cestino, quindi si sincronizza su Cloud, PC e smartphone.
// ==========================================================================
const CESTINO_GIORNI = 60;
const CESTINO_MAX = 300;
const CESTINO_TIPI = {
  terapia: { icona: '💊', nome: 'Terapia' },
  visita: { icona: '📅', nome: 'Visita' },
  ausilio: { icona: '🦽', nome: 'Ausilio' },
  annotazione: { icona: '📝', nome: 'Annotazioni diario' },
  glicemia: { icona: '🩸', nome: 'Glicemia' },
  paziente: { icona: '👤', nome: 'Cartella assistito' }
};

function cestinoEsc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}

function cestinoPulisciScaduti() {
  if (!AppData || !Array.isArray(AppData._cestino)) return;
  const limite = Date.now() - CESTINO_GIORNI * 86400000;
  AppData._cestino = AppData._cestino.filter(function (e) { return e && e.ts > limite; });
}

function cestinoAggiungi(tipo, etichetta, dettaglio, item, paz) {
  try {
    AppData._cestino = Array.isArray(AppData._cestino) ? AppData._cestino : [];
    const entryId = 'cst_' + Date.now() + '_' + Math.floor(Math.random() * 1000);
    AppData._cestino.unshift({
      id: entryId,
      tipo: tipo,
      etichetta: etichetta || '',
      dettaglio: dettaglio || '',
      pazienteId: paz ? paz.id : '',
      pazienteNome: paz ? paz.nome : '',
      ts: Date.now(),
      eliminatoDa: localStorage.getItem('milella_user_nome') || localStorage.getItem('milella_last_authenticated_user') || 'Admin',
      item: JSON.parse(JSON.stringify(item))
    });
    cestinoPulisciScaduti();
    if (AppData._cestino.length > CESTINO_MAX) AppData._cestino.length = CESTINO_MAX;
    if (typeof cestinoAggiornaBadge === 'function') cestinoAggiornaBadge();
    return entryId;
  } catch (e) {
    console.warn('Cestino: impossibile archiviare', e);
    return null;
  }
}

function cestinoAggiornaBadge() {
  const n = (AppData && Array.isArray(AppData._cestino)) ? AppData._cestino.length : 0;
  document.querySelectorAll('.cestino-count-badge').forEach(function (el) {
    el.textContent = n;
    el.style.display = n > 0 ? 'inline-flex' : 'none';
  });
}

function apriModalCestino() {
  try {
    if (typeof chiudiMenuStrumenti === 'function') chiudiMenuStrumenti();
    if (typeof chiudiMenuOSSTop === 'function') chiudiMenuOSSTop();
    cestinoPulisciScaduti();
    const m = document.getElementById('modal-cestino');
    if (m && m.parentElement !== document.body) {
      document.body.appendChild(m);
    }
    renderCestino();
    openModal('modal-cestino');
    if (m) {
      m.style.zIndex = '25000350';
      m.classList.add('active');
      m.style.display = 'flex';
    }
  } catch (err) {
    console.error('Errore durante apertura Cestino:', err);
  }
}

function renderCestino() {
  const box = document.getElementById('cestino-lista');
  if (!box) return;
  const lista = (AppData && Array.isArray(AppData._cestino)) ? AppData._cestino : [];
  cestinoAggiornaBadge();
  const btnSvuota = document.getElementById('cestino-btn-svuota');
  if (btnSvuota) btnSvuota.style.display = lista.length ? 'inline-flex' : 'none';
  if (!lista.length) {
    box.innerHTML = '<div class="cestino-vuoto"><div style="font-size:42px;">✨</div><b>Il Cestino è vuoto</b><span>Tutto ciò che elimini (farmaci, visite, note, cartelle) compare qui e resta recuperabile per ' + CESTINO_GIORNI + ' giorni.</span></div>';
    return;
  }
  box.innerHTML = lista.map(function (e) {
    const t = CESTINO_TIPI[e.tipo] || { icona: '🗂️', nome: e.tipo || 'Elemento' };
    const ts = e.ts || Date.now();
    const giorniRimasti = Math.max(0, Math.ceil((ts + CESTINO_GIORNI * 86400000 - Date.now()) / 86400000));
    const quando = new Date(ts).toLocaleString('it-IT', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
    return '<div class="cestino-item">' +
      '<div class="cestino-item-ico">' + t.icona + '</div>' +
      '<div class="cestino-item-body">' +
      '<div class="cestino-item-titolo">' + cestinoEsc(e.etichetta || 'Elemento eliminato') + '</div>' +
      '<div class="cestino-item-meta"><span class="cestino-tag">' + cestinoEsc(t.nome) + '</span>' +
      (e.pazienteNome && e.tipo !== 'paziente' ? '<span>👤 ' + cestinoEsc(e.pazienteNome) + '</span>' : '') +
      '<span>🕒 ' + quando + '</span>' +
      '<span class="' + (giorniRimasti <= 7 ? 'cestino-scade' : '') + '">⏳ ' + giorniRimasti + ' gg</span></div>' +
      (e.dettaglio ? '<div class="cestino-item-dett">' + cestinoEsc(e.dettaglio) + '</div>' : '') +
      '</div>' +
      '<div class="cestino-item-azioni">' +
      '<button type="button" class="btn cestino-btn-ripristina" onclick="cestinoRipristina(\'' + e.id + '\')">↩️ Ripristina</button>' +
      '<button type="button" class="btn cestino-btn-elimina" onclick="cestinoEliminaDefinitivo(\'' + e.id + '\')" title="Elimina definitivamente questo elemento">🗑️ Elimina definitivamente</button>' +
      '</div></div>';
  }).join('');
}

function cestinoRipristina(id) {
  try {
    const lista = (AppData && Array.isArray(AppData._cestino)) ? AppData._cestino : [];
    const e = lista.find(function (x) { return x.id === id; });
    if (!e) return;
    const item = JSON.parse(JSON.stringify(e.item));
    let messaggio = '';

    if (e.tipo === 'paziente') {
      if (AppData.pazienti.some(function (p) { return p.id === item.id; })) {
        showToast('Questa cartella è già presente.', 'warning');
      } else {
        AppData.pazienti.push(item);
        AppData._deletedPazienti = (AppData._deletedPazienti || []).filter(function (x) { return x !== item.id; });
      }
      messaggio = 'Cartella di "' + item.nome + '" ripristinata con tutti i dati.';
    } else {
      const p = (AppData.pazienti || []).find(function (x) { return x.id === e.pazienteId; }) || (typeof getActivePaziente === 'function' ? getActivePaziente() : null);
      if (!p) {
        showToast('La cartella di ' + (e.pazienteNome || 'questo assistito') + ' non esiste più: ripristina prima la cartella dal Cestino.', 'warning');
        return;
      }
      if (e.tipo === 'terapia') {
        p.terapie = p.terapie || [];
        if (p.terapie.some(function (t) { return t.id === item.id; })) item.id = Date.now();
        p.terapie.push(item);
      } else if (e.tipo === 'visita') {
        p.visite = p.visite || [];
        if (p.visite.some(function (v) { return v.id === item.id; })) item.id = Date.now();
        p.visite.push(item);
      } else if (e.tipo === 'ausilio') {
        p.ausili = p.ausili || [];
        p.ausili.push(item);
      } else if (e.tipo === 'annotazione' || e.tipo === 'glicemia') {
        p.registrazioni = p.registrazioni || [];
        const arr = Array.isArray(item) ? item : [item];
        arr.forEach(function (r) {
          if (!p.registrazioni.some(function (x) { return String(x.id) === String(r.id); })) p.registrazioni.push(r);
        });
      }
      messaggio = '"' + e.etichetta + '" ripristinato per ' + (p.nome || 'l\'assistito') + '.';
    }

    AppData._cestino = lista.filter(function (x) { return x.id !== id; });
    saveDb();
    renderCestino();
    if (typeof cestinoAggiornaBadge === 'function') cestinoAggiornaBadge();
    if (typeof renderAll === 'function') renderAll();
    if (typeof renderTerapie === 'function') renderTerapie();
    if (typeof renderVisite === 'function') renderVisite();
    if (typeof renderDashboard === 'function') renderDashboard();
    if (typeof renderDiario === 'function') renderDiario();
    if (typeof renderDiarioMobile === 'function') renderDiarioMobile();
    if (typeof renderPazientiSelector === 'function') renderPazientiSelector();
    const curP = typeof getActivePaziente === 'function' ? getActivePaziente() : null;
    if (curP && typeof renderMobileNativeView === 'function') renderMobileNativeView(curP.terapie || [], curP);
    showToast(messaggio + ' ↩️', 'success');
  } catch (err) {
    console.error('Errore durante ripristino dal Cestino:', err);
    showToast('Errore durante il ripristino.', 'danger');
  }
}

async function cestinoEliminaDefinitivo(id) {
  var authAdmin = await window.richiediPinAdminPerCancellazione('Inserisci il PIN / Password Amministratore (SOS999) per eliminare definitivamente questo elemento dal Cestino:');
  if (!authAdmin) {
    showToast('Operazione annullata: password Admin non fornita.', 'warning');
    return;
  }

  try {
    const lista = (AppData && Array.isArray(AppData._cestino)) ? AppData._cestino : [];
    const e = lista.find(function (x) { return x.id === id; });
    if (!e) return;
    let ok = false;
    try {
      if (typeof customConfirm === 'function') {
        ok = await customConfirm(
          'Elimina per sempre',
          '"' + e.etichetta + '" verrà cancellato DEFINITIVAMENTE e non sarà più recuperabile.',
          '⛔',
          'Elimina per sempre'
        );
      } else {
        ok = confirm('Vuoi eliminare definitivamente "' + e.etichetta + '"? Non sarà più recuperabile.');
      }
    } catch (confErr) {
      ok = confirm('Vuoi eliminare definitivamente "' + e.etichetta + '"? Non sarà più recuperabile.');
    }
    if (!ok) return;
    AppData._cestino = lista.filter(function (x) { return x.id !== id; });
    saveDb();
    renderCestino();
    if (typeof cestinoAggiornaBadge === 'function') cestinoAggiornaBadge();
    showToast('Elemento eliminato definitivamente.', 'info');
  } catch (err) {
    console.error('Errore eliminazione definitiva cestino:', err);
    showToast('Errore durante l\'eliminazione.', 'danger');
  }
}

async function cestinoSvuota() {
  var authAdmin = await window.richiediPinAdminPerCancellazione('Inserisci il PIN / Password Amministratore (SOS999) per svuotare DEFINITIVAMENTE l\'intero Cestino:');
  if (!authAdmin) {
    showToast('Operazione annullata: password Admin non fornita.', 'warning');
    return;
  }

  try {
    const n = (AppData && Array.isArray(AppData._cestino)) ? AppData._cestino.length : 0;
    if (!n) {
      showToast('Il Cestino è già vuoto.', 'info');
      return;
    }
    let ok = false;
    try {
      if (typeof customConfirm === 'function') {
        ok = await customConfirm(
          'Svuota il Cestino',
          'Verranno cancellati DEFINITIVAMENTE tutti i ' + n + ' elementi del Cestino. Dopo questa operazione non sarà più possibile recuperarli.',
          '⛔',
          'Svuota definitivamente'
        );
      } else {
        ok = confirm('Verranno cancellati DEFINITIVAMENTE tutti i ' + n + ' elementi del Cestino. Procedere?');
      }
    } catch (confErr) {
      ok = confirm('Verranno cancellati DEFINITIVAMENTE tutti i ' + n + ' elementi del Cestino. Procedere?');
    }
    if (!ok) return;
    AppData._cestino = [];
    saveDb();
    renderCestino();
    if (typeof cestinoAggiornaBadge === 'function') cestinoAggiornaBadge();
    showToast('Cestino svuotato con successo.', 'success');
  } catch (err) {
    console.error('Errore svuotamento cestino:', err);
    showToast('Errore svuotamento cestino.', 'danger');
  }
}
window.apriModalCestino = apriModalCestino;
window.renderCestino = renderCestino;
window.cestinoRipristina = cestinoRipristina;
window.cestinoEliminaDefinitivo = cestinoEliminaDefinitivo;
window.cestinoSvuota = cestinoSvuota;

const CESTINO_AVVISO = ' Non viene cancellato subito: finisce nel Cestino (Opzioni → Cestino & Ripristino) e potrai ripristinarlo entro ' + CESTINO_GIORNI + ' giorni.';

// CODICE PUK DI SICUREZZA SEGRETO PER CANCELLAZIONI PROTETTE
const PUK_SEGRETO_OSS = 'SOS999';

function chiediPukSicurezza() {
  return new Promise((resolve) => {
    const modal = document.getElementById('modal-puk-auth');
    const input = document.getElementById('puk-input-field');
    const errorMsg = document.getElementById('puk-error-msg');
    const btnConfirm = document.getElementById('puk-btn-confirm');
    const btnCancel = document.getElementById('puk-btn-cancel');

    input.value = '';
    errorMsg.style.display = 'none';
    modal.classList.add('active');
    setTimeout(() => input.focus(), 150);

    const cleanup = () => {
      modal.classList.remove('active');
      btnConfirm.removeEventListener('click', verify);
      btnCancel.removeEventListener('click', onCancel);
      input.removeEventListener('keydown', onKey);
    };

    const verify = () => {
      const inserito = input.value.trim().toUpperCase();
      if (inserito === PUK_SEGRETO_OSS) {
        cleanup();
        resolve(true);
      } else {
        errorMsg.style.display = 'block';
        input.value = '';
        input.focus();
      }
    };

    const onCancel = () => {
      cleanup();
      resolve(false);
    };

    const onKey = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        verify();
      } else if (e.key === 'Escape') {
        onCancel();
      }
    };

    btnConfirm.addEventListener('click', verify);
    btnCancel.addEventListener('click', onCancel);
    input.addEventListener('keydown', onKey);
  });
}

// Notifica Toast Elegante al posto dei popup brutti del browser
function showToast(messaggio, tipo = 'success') {
  const existing = document.querySelector('.toast-notification');
  if (existing) existing.remove();

  const toast = document.createElement('div');
  toast.className = 'toast-notification';
  toast.style.borderLeftColor = tipo === 'success' ? '#10b981' : (tipo === 'warning' ? '#f59e0b' : '#ef4444');

  // Calcolo intelligente della posizione verticale per evitare qualsiasi sovrapposizione con il banner Cloud Sync
  var adminToast = document.getElementById('careassist-admin-sync-toast');
  var topPos = (window.innerWidth <= 768 ? '16px' : '20px');
  if (adminToast && adminToast.isConnected && adminToast.offsetHeight > 0) {
    var rect = adminToast.getBoundingClientRect();
    topPos = Math.max(76, rect.bottom + 12) + 'px';
  }
  toast.style.top = topPos;

  var iconEmoji = tipo === 'success' ? '✅' : (tipo === 'warning' ? '⚠️' : '🚨');
  toast.innerHTML = `
    <span style="font-size:18px; flex-shrink:0;">${iconEmoji}</span>
    <span style="line-height:1.35;">${messaggio}</span>
  `;
  document.body.appendChild(toast);
  setTimeout(() => {
    toast.style.animation = 'fadeIn 0.2s reverse forwards';
    setTimeout(() => toast.remove(), 250);
  }, 3400);
}

function cambiaPaziente(pazId) {
  if (!pazId || !AppData) return;
  AppData.activePazienteId = pazId;
  try { localStorage.setItem('careassist_active_paziente_id', pazId); } catch (e) { }

  // Assicura array registrazioni valido sul paziente
  var p = (AppData.pazienti || []).find(function (x) { return x.id === pazId; });
  if (p && !Array.isArray(p.registrazioni)) {
    p.registrazioni = [];
  }

  try {
    localStorage.setItem(DB_KEY, JSON.stringify(AppData));
  } catch (eSave) {
    console.warn('localStorage save error:', eSave);
  }

  try {
    if (typeof renderAll === 'function') renderAll();
  } catch (eRender) {
    console.warn('renderAll error:', eRender);
  }

  // Renderizza subito la vista mobile nativa
  try {
    var pAttivo = (typeof getActivePaziente === 'function') ? getActivePaziente() : p;
    if (pAttivo && typeof renderMobileNativeView === 'function') {
      renderMobileNativeView(pAttivo.terapie || [], pAttivo);
    }
  } catch (eMob) { }

  var tabSection = document.getElementById('tab-epatologia');
  if (tabSection && (tabSection.style.display === 'block' || tabSection.style.display === 'flex' || tabSection.classList.contains('active'))) {
    if (typeof renderEpatologiaView === 'function') renderEpatologiaView();
  }
}
window.cambiaPaziente = cambiaPaziente;

// Gestione Intelligente Patologie Cliniche (Chip Rapidi & Catalogo Dinamico)
function togglePatologiaChip(elem, patologiaNome) {
  const textarea = document.getElementById('nuovo-paz-patologie-testo');
  if (!textarea) return;

  let currentText = textarea.value.trim();
  let righe = currentText ? currentText.split(/[\n,]+/).map(s => s.trim()).filter(s => s.length > 0) : [];

  const index = righe.findIndex(r => r.toLowerCase() === patologiaNome.toLowerCase());
  if (index >= 0) {
    // Rimuove
    righe.splice(index, 1);
    elem.classList.remove('selezionato');
    elem.textContent = '+ ' + patologiaNome.split(' ')[0];
  } else {
    // Aggiunge
    righe.push(patologiaNome);
    elem.classList.add('selezionato');
    elem.textContent = '✓ ' + patologiaNome.split(' ')[0];
  }

  textarea.value = righe.join('\n');
}

function aggiungiPatologiaPersonalizzata() {
  const input = document.getElementById('nuovo-paz-input-nuova-patologia');
  const textarea = document.getElementById('nuovo-paz-patologie-testo');
  const datalist = document.getElementById('datalist-patologie');
  const containerChip = document.getElementById('container-chip-patologie');

  if (!input || !textarea) return;

  const nuovaPatologia = input.value.trim();
  if (!nuovaPatologia) {
    showToast('Digita il nome della patologia da aggiungere', 'warning');
    return;
  }

  // Aggiunge alla textarea
  let currentText = textarea.value.trim();
  let righe = currentText ? currentText.split(/[\n,]+/).map(s => s.trim()).filter(s => s.length > 0) : [];

  if (!righe.some(r => r.toLowerCase() === nuovaPatologia.toLowerCase())) {
    righe.push(nuovaPatologia);
    textarea.value = righe.join('\n');
  }

  // Aggiunge al datalist suggerimenti per il futuro
  if (datalist && ![...datalist.options].some(opt => opt.value.toLowerCase() === nuovaPatologia.toLowerCase())) {
    const opt = document.createElement('option');
    opt.value = nuovaPatologia;
    datalist.appendChild(opt);
  }

  // Aggiunge un nuovo chip visivo istantaneo
  if (containerChip) {
    const nuovoChip = document.createElement('span');
    nuovoChip.className = 'chip-patologia selezionato';
    nuovoChip.textContent = '✓ ' + nuovaPatologia;
    nuovoChip.onclick = function () {
      togglePatologiaChip(this, nuovaPatologia);
    };
    containerChip.appendChild(nuovoChip);
  }

  input.value = '';
  showToast(`Patologia "${nuovaPatologia}" aggiunta ed inclusa nel catalogo!`);
}

function impostaAllergiaRapida(prefix, valore) {
  const el = document.getElementById(prefix + '-paz-allergie');
  if (el) el.value = valore;
}

function aggiungiAllergiaRapida(prefix, allergia) {
  const el = document.getElementById(prefix + '-paz-allergie');
  if (!el) return;
  const cur = (el.value || '').trim();
  if (!cur || cur.toLowerCase().includes('nessuna') || cur.toLowerCase().includes('nessun')) {
    el.value = allergia;
  } else {
    const list = cur.split(',').map(s => s.trim().toLowerCase());
    if (!list.includes(allergia.toLowerCase())) {
      el.value = cur + ', ' + allergia;
    }
  }
}
window.impostaAllergiaRapida = impostaAllergiaRapida;
window.aggiungiAllergiaRapida = aggiungiAllergiaRapida;

function salvaNuovoPaziente(e) {
  e.preventDefault();
  const nome = (document.getElementById('nuovo-paz-nome')?.value || '').trim();

  // Sincronizza sempre la data dai select a cascata prima del salvataggio
  sincronizzaDataDaSelects('nuovo');
  let dataNascita = (document.getElementById('nuovo-paz-nascita')?.value || '').trim();
  if (!dataNascita) {
    const g = (document.getElementById('nuovo-paz-nascita-giorno')?.value || '15').padStart(2, '0');
    const m = (document.getElementById('nuovo-paz-nascita-mese')?.value || '05').padStart(2, '0');
    const a = document.getElementById('nuovo-paz-nascita-anno')?.value || '1938';
    dataNascita = `${a}-${m}-${g}`;
  }

  if (!nome) {
    alert('Attenzione: inserisci il Nome e Cognome dell\'assistito.');
    return;
  }
  const sesso = document.getElementById('nuovo-paz-sesso')?.value || 'M';
  const mobilita = document.getElementById('nuovo-paz-mobilita')?.value || 'deambulante';
  const indirizzo = (document.getElementById('nuovo-paz-indirizzo')?.value || '').trim();
  const telCasa = formattaNumeroTelefonico(document.getElementById('nuovo-paz-telefono').value.trim());
  const cellulare = formattaNumeroTelefonico(document.getElementById('nuovo-paz-cellulare').value.trim());
  const parenteNome = document.getElementById('nuovo-paz-parente-nome').value.trim();
  const parenteCell = formattaNumeroTelefonico(document.getElementById('nuovo-paz-parente-cell').value.trim());
  const elNParenEmail = document.getElementById('nuovo-paz-parente-email');
  const parenteEmail = elNParenEmail ? elNParenEmail.value.trim() : '';
  const elNParenPec = document.getElementById('nuovo-paz-parente-pec');
  const parentePec = elNParenPec ? elNParenPec.value.trim() : '';

  const elAllergieNuovo = document.getElementById('nuovo-paz-allergie');
  const allergieNuovo = elAllergieNuovo ? elAllergieNuovo.value.trim() : 'Nessuna nota';

  const patologieTesto = (document.getElementById('nuovo-paz-patologie-testo')?.value || '').trim();
  const elCpap = document.getElementById('nuovo-paz-cpap');
  const isCpap = elCpap ? elCpap.checked : false;
  const elMaterasso = document.getElementById('nuovo-paz-materasso');
  const isMaterasso = elMaterasso ? elMaterasso.checked : false;
  const elBombola = document.getElementById('nuovo-paz-bombola-attiva');
  const bombolaStato = elBombola ? elBombola.value : 'piena';
  const elDataBombola = document.getElementById('nuovo-paz-data-bombola');
  const dataBombola = elDataBombola ? elDataBombola.value : '';
  const elAltriAusili = document.getElementById('nuovo-paz-altri-ausili');
  const altriAusili = elAltriAusili ? elAltriAusili.value.trim() : '';

  const medicoNome = document.getElementById('nuovo-paz-medico-nome').value.trim();
  const medicoTel = formattaNumeroTelefonico(document.getElementById('nuovo-paz-medico-tel').value.trim());
  const medicoEmail = document.getElementById('nuovo-paz-medico-email').value.trim();
  const farmaciaNome = document.getElementById('nuovo-paz-farmacia').value.trim();
  const farmaciaTel = formattaNumeroTelefonico(document.getElementById('nuovo-paz-farmacia-tel').value.trim());

  if (!nome) {
    alert('Attenzione: inserisci il Nome e Cognome dell\'assistito.');
    return;
  }
  console.log('[salvaNuovoPaziente] Creazione assistito:', nome, dataNascita);

  const newId = 'paz_' + Date.now();
  const newPaz = createPazienteTemplate(newId, nome, dataNascita, patologieTesto, sesso);
  newPaz.sesso = sesso;
  newPaz.allettato = (mobilita === 'allettato');
  newPaz.indirizzo = indirizzo;
  newPaz.telefonoFisso = telCasa;
  newPaz.cellulare = cellulare;
  newPaz.moglieNome = parenteNome;
  newPaz.moglieCellulare = parenteCell;
  newPaz.caregiverEmail = parenteEmail;
  newPaz.moglieEmail = parenteEmail;
  newPaz.caregiverPec = parentePec;
  newPaz.mogliePec = parentePec;
  newPaz.allergie = allergieNuovo || 'Nessuna nota';

  newPaz.medico = medicoNome || 'Dott. Curante';
  newPaz.medicoNome = medicoNome;
  newPaz.medicoTel = medicoTel;
  newPaz.medicoEmail = medicoEmail;
  newPaz.farmaciaDiRiferimento = farmaciaNome || 'Farmacia di Riferimento';
  newPaz.farmaciaTelefono = farmaciaTel;

  // Elaborazione Patologie Personalizzate
  newPaz.patologie = [];
  if (patologieTesto) {
    const righe = patologieTesto.split(/[\n,]+/).map(s => s.trim()).filter(s => s.length > 0);
    newPaz.patologie.push(...righe);
  }
  if (newPaz.allettato && !newPaz.patologie.some(p => p.toLowerCase().includes('piaghe') || p.toLowerCase().includes('allettato'))) {
    newPaz.patologie.unshift('Paziente allettato a rischio piaghe da decubito (Rotazione q2h)');
  }

  // Elaborazione Ausili dal Catalogo Interattivo
  newPaz.ausili = estraiAusiliSelezionatiDaForm('nuovo-aus');

  // Se è allettato e non ha il materasso spuntato, aggiungilo come presidio di sicurezza
  if (newPaz.allettato && !newPaz.ausili.some(a => (a.tipo || '').toLowerCase().includes('materasso'))) {
    newPaz.ausili.unshift({
      tipo: 'Materasso Antidecubito a Pressione Alternata',
      utilizzo: 'Gonfiaggio continuo a ciclo alternato per prevenzione lesioni da pressione',
      prossimaRichiesta: '',
      stato: 'In uso attivo'
    });
  }

  // Genera promemoria scadenze rifornimento nel calendario visite
  newPaz.ausili.forEach(a => {
    if (a.dataScadenza) {
      newPaz.visite.push({
        id: Date.now() + Math.floor(Math.random() * 1000),
        data: a.dataScadenza,
        ora: '10:00',
        medico: medicoNome || 'ASL / Servizio Territoriale',
        motivo: `Rinnovo ricetta / Rifornimento ASL per ${a.tipo}`,
        fatto: false
      });
    }
  });

  AppData.pazienti.push(newPaz);
  AppData.activePazienteId = newId;

  closeModal('modal-nuovo-paziente');
  document.getElementById('form-nuovo-paziente').reset();
  const preview = document.getElementById('nuovo-paz-eta-preview');
  if (preview) preview.value = '';
  saveDb();
  showToast(`Cartella clinica completa creata per "${nome}"!`);
}

// Funzione intelligente di formattazione elegante dei numeri di telefono italiani
function formattaNumeroTelefonico(inputStr) {
  if (!inputStr) return '';
  // Rimuovi spazi e caratteri speciali tranne il + iniziale
  let str = inputStr.trim();
  const hasPlus = str.startsWith('+');
  let clean = str.replace(/[^0-9]/g, '');

  if (!clean) return inputStr;

  // Se c'è prefisso internazionale 39 o +39
  let prefix = '';
  if (hasPlus && clean.startsWith('39')) {
    prefix = '+39 ';
    clean = clean.slice(2);
  }

  // 1. Cellulari (iniziano con 3, solitamente 10 cifre: 338 000 00 01 oppure 347 126 59 71)
  if (clean.startsWith('3')) {
    if (clean.length === 10) {
      return prefix + `${clean.slice(0, 3)} ${clean.slice(3, 6)} ${clean.slice(6, 8)} ${clean.slice(8, 10)}`;
    } else if (clean.length === 9) {
      return prefix + `${clean.slice(0, 3)} ${clean.slice(3, 6)} ${clean.slice(6, 9)}`;
    }
  }

  // 2. Fissi con prefisso a 3 cifre come Bari 080 (080 561 57 14 oppure 080 557 4490 -> 080 557 44 90)
  if (clean.startsWith('080') || clean.startsWith('081') || clean.startsWith('011') || clean.startsWith('051') || clean.startsWith('055') || clean.startsWith('091')) {
    const pref = clean.slice(0, 3);
    const rest = clean.slice(3);
    if (rest.length === 7) {
      return prefix + `${pref} ${rest.slice(0, 3)} ${rest.slice(3, 5)} ${rest.slice(5, 7)}`;
    } else if (rest.length === 6) {
      return prefix + `${pref} ${rest.slice(0, 3)} ${rest.slice(3, 6)}`;
    } else if (rest.length > 3) {
      return prefix + `${pref} ${rest.slice(0, 3)} ${rest.slice(3)}`;
    }
  }

  // 3. Fissi Roma/Milano 06 / 02
  if (clean.startsWith('06') || clean.startsWith('02')) {
    const pref = clean.slice(0, 2);
    const rest = clean.slice(2);
    if (rest.length === 8) {
      return prefix + `${pref} ${rest.slice(0, 4)} ${rest.slice(4, 6)} ${rest.slice(6, 8)}`;
    } else if (rest.length === 7) {
      return prefix + `${pref} ${rest.slice(0, 3)} ${rest.slice(3, 5)} ${rest.slice(5, 7)}`;
    }
  }

  // Fissi italiani a 10 cifre (es. Potenza 0971 xxx xxx)
  if (clean.startsWith('0') && clean.length === 10) {
    return prefix + `${clean.slice(0, 4)} ${clean.slice(4, 7)} ${clean.slice(7, 10)}`;
  }

  // Generico: cellulare o recapito a 10 cifre
  if (clean.length === 10) {
    return prefix + `${clean.slice(0, 3)} ${clean.slice(3, 6)} ${clean.slice(6, 8)} ${clean.slice(8, 10)}`;
  }

  // Se contiene testo o più numeri (es. orari o note), mantieni l'input dell'utente senza alterarlo
  return inputStr;
}


// Funzioni Pianificatore Orari Settimanali Intuitivo

function impostaGiornoChiuso(giornoId) {
  const elOra = document.getElementById('orario-giorno-' + giornoId);
  const elSede = document.getElementById('sede-giorno-' + giornoId);
  const elBadge = document.getElementById('badge-' + giornoId);
  if (elOra) elOra.value = '';
  if (elSede) elSede.value = 'Chiuso';
  if (elBadge) {
    elBadge.textContent = 'Chiuso';
    elBadge.style.background = '#f1f5f9';
    elBadge.style.color = '#94a3b8';
  }
  sincronizzaPlannerVersoTesto();
}

