function aggiornaInfoModalCarico() {
  const farmId = parseInt(document.getElementById('ricarica-farmaco-select').value);
  const p = getActivePaziente();
  if (!p || !farmId) return;
  const t = p.terapie.find(item => item.id === farmId);
  const help = document.getElementById('ricarica-scatole-help');
  if (t && help) {
    help.innerHTML = `Ogni scatola di <b>${t.farmaco}</b> contiene <b>${t.cprPerScatola || 28} compresse</b>. Scorta attuale a casa: <b>${t.scorta} cpr</b>.`;
  }
}

function salvaRicaricaScorta(e) {
  e.preventDefault();
  const p = getActivePaziente();
  if (!p) return;

  const farmId = parseInt(document.getElementById('ricarica-farmaco-select').value);
  const t = p.terapie.find(item => item.id === farmId);
  if (!t) return;

  const modalita = document.querySelector('input[name="modalita_carico"]:checked').value;
  let cprAggiunte = 0;
  let descEvento = '';

  if (modalita === 'esatto') {
    const valoreEsatto = parseInt(document.getElementById('ricarica-num-esatto').value);
    if (isNaN(valoreEsatto) || valoreEsatto < 0) {
      showToast('Inserisci un conteggio valido di capsule.', 'warning');
      return;
    }
    const diff = valoreEsatto - (t.scorta || 0);
    t.scorta = valoreEsatto;
    cprAggiunte = diff;
    descEvento = `Inventario Esatto: Scorta allineata a ${valoreEsatto} compresse conteggiate dal paziente/operatore (variazione: ${diff >= 0 ? '+' : ''}${diff}).`;
  } else if (modalita === 'scatole') {
    const numScatole = parseInt(document.getElementById('ricarica-num-scatole').value) || 1;
    cprAggiunte = (t.cprPerScatola || 28) * numScatole;
    descEvento = `Carico Farmacia: Ritiro di ${numScatole} scatola/e di ${t.farmaco} (+${cprAggiunte} compresse).`;
  } else {
    cprAggiunte = parseInt(document.getElementById('ricarica-num-sfuse').value) || 0;
    if (cprAggiunte <= 0) {
      showToast('Inserisci un numero valido di capsule sfuse.', 'warning');
      return;
    }
    descEvento = `Inventario Domiciliare: Aggiunte ${cprAggiunte} capsule/compresse sfuse trovate a casa per ${t.farmaco}.`;
  }

  t.scorta += cprAggiunte;
  const now = new Date();
  t.ultimoRitiro = now.toISOString();

  // Registra nel diario
  p.registrazioni.push({
    id: 'log_' + Date.now(),
    tipo: 'scorta',
    farmacoId: t.id,
    farmaco: t.farmaco,
    azione: modalita === 'scatole' ? 'carico_farmacia' : 'carico_sfuse',
    cprAggiunte: cprAggiunte,
    timestamp: now.toISOString(),
    desc: `${descEvento} Nuova scorta totale: ${t.scorta} compresse.`,
    operatore: 'Operatore OSS / Famiglia'
  });

  closeModal('modal-ricarica-scorta');
  // Reset campi
  document.getElementById('ricarica-num-scatole').value = 1;
  document.getElementById('ricarica-num-sfuse').value = '';
  saveDb();
  showToast(`Aggiunte +${cprAggiunte} compresse a "${t.farmaco}". Scorta totale: ${t.scorta} cpr!`);
}

// ==========================================================================
// MODULO RICHIESTA RICETTE FARMACI AL MEDICO (WHATSAPP, EMAIL O ENTRAMBI)
// ==========================================================================
function apriRichiestaRicetteMedico() {
  const p = getActivePaziente();
  if (!p) return;

  // Mostra nome medico e farmacia
  const medicoBadge = document.getElementById('richiesta-medico-nome-badge');
  if (medicoBadge) {
    medicoBadge.textContent = p.medicoNome || p.medico || 'Dott. di Famiglia';
  }

  // Genera lista checkbox farmaci
  const container = document.getElementById('richiesta-farmaci-checkboxes');
  if (container) {
    container.innerHTML = (p.terapie || []).map(t => {
      const giorni = t.scorta > 0 ? t.scorta : 0;
      const sogliaAlert = Math.min(30, Math.max(1, parseInt(t.giorniAlert) || 7));
      const isUrgent = giorni <= sogliaAlert;
      return `
        <label style="display:flex; align-items:center; justify-content:space-between; padding:6px 4px; border-bottom:1px solid #f1f5f9; cursor:pointer; font-size:13px;">
          <div style="display:flex; align-items:center; gap:8px;">
            <input type="checkbox" class="chk-richiesta-farmaco" value="${t.id}" ${isUrgent ? 'checked' : ''} onchange="aggiornaAnteprimaTestoRichiesta()" style="width:16px; height:16px;">
            <span style="font-weight:700; color:#0f172a;">${t.farmaco}</span>
            <small style="color:#64748b;">(${t.dosaggio})</small>
          </div>
          <div>
            <span class="badge ${giorni <= 5 ? 'badge-danger' : (giorni <= 12 ? 'badge-warning' : 'badge-primary')}" style="font-size:10px;">
              ${t.scorta} cpr (~${giorni} gg)
            </span>
          </div>
        </label>
      `;
    }).join('') || '<div style="color:#94a3b8; font-size:12px;">Nessun farmaco presente in terapia.</div>';
  }

  aggiornaAnteprimaTestoRichiesta();
  openModal('modal-richiesta-medico');
}

function selezionaTuttiFarmaciRichiesta(stato) {
  document.querySelectorAll('.chk-richiesta-farmaco').forEach(chk => chk.checked = stato);
  aggiornaAnteprimaTestoRichiesta();
}

function selezionaSoloInScadenzaRichiesta() {
  const p = getActivePaziente();
  if (!p) return;
  document.querySelectorAll('.chk-richiesta-farmaco').forEach(chk => {
    const t = p.terapie.find(item => item.id === parseInt(chk.value));
    if (t) {
      chk.checked = (t.scorta <= 12);
    }
  });
  aggiornaAnteprimaTestoRichiesta();
}

function generaTestoRichiesta() {
  const p = getActivePaziente();
  if (!p) return '';

  const checkedIds = Array.from(document.querySelectorAll('.chk-richiesta-farmaco:checked')).map(c => parseInt(c.value));
  const farmaciSelezionati = (p.terapie || []).filter(t => checkedIds.includes(t.id));
  const noteExtra = document.getElementById('richiesta-note-extra') ? document.getElementById('richiesta-note-extra').value.trim() : '';

  const medicoNome = p.medicoNome || p.medico || p.medicoCurante || 'Dottore';
  const farmaciaNome = p.farmaciaDiRiferimento || 'Farmacia MACARIO';
  const oggi = new Date().toLocaleDateString('it-IT');

  let elenco = '';
  if (farmaciSelezionati.length === 0) {
    elenco = '(Nessun farmaco selezionato)';
  } else {
    elenco = farmaciSelezionati.map((t, idx) => {
      const dt = new Date();
      const scorta = typeof t.scorta !== 'undefined' ? t.scorta : 0;
      const ggAutonomia = (typeof calcolaGiorniAutonomiaFarmaco === 'function') ? calcolaGiorniAutonomiaFarmaco(t) : scorta;
      dt.setDate(dt.getDate() + (ggAutonomia > 0 ? ggAutonomia : 0));
      const fineScortaStr = ggAutonomia > 0 ? dt.toLocaleDateString('it-IT') : 'ESAURITO OGGI';
      const soglia = Math.min(30, Math.max(1, parseInt(t.giorniAlert) || 7));
      const urgenza = scorta <= 0 ? '🔴 URGENTE (Scorta a zero)' : (ggAutonomia <= soglia ? '⚠️ IN SCADENZA (Autonomia: ' + ggAutonomia + ' gg)' : 'Autonomia: ' + ggAutonomia + ' gg');
      const schemaNote = t.cadenzaTipo === 'alternata_mezza_intera' ? ' [Posologia: 1/2 cpr o 1 cpr a giorni alterni]' : '';
      return (idx + 1) + '. *' + t.farmaco + '* (' + (t.dosaggio || '1 dose') + schemaNote + ')\n   ↳ Rimanenza: ' + scorta + ' cpr (~' + ggAutonomia + ' gg) • ' + urgenza;
    }).join('\n\n');
  }

  const pulitoNome = (p.nome || '').replace(/\s*\(\d+\s*anni\)/gi, '').trim();
  const dataNascitaFmt = (typeof formattaDataNascitaItaliana === 'function') ? formattaDataNascitaItaliana(p.dataNascita, false) : (p.dataNascita || '--');
  const caregiverInfo = p.caregiverNome || p.caregiver || p.moglieNome || (p.nome && p.nome.includes('Rosa') ? 'Maria Carmela (Figlia / Caregiver)' : 'M. Angela (Caregiver)');
  const caregiverTel = p.caregiverCellulare || p.caregiverTel || p.moglieCellulare || (p.nome && p.nome.includes('Rosa') ? '338 739 76 71' : '338 000 00 02');

  let testo = 'Gentile ' + medicoNome + ',\n\n';
  testo += 'Le invio la presente richiesta di rinnovo prescrizioni / ricette dematerializzate per:\n';
  testo += '👤 *Paziente:* ' + pulitoNome + '\n';
  testo += '🎂 *Data di Nascita:* ' + dataNascitaFmt + '\n';
  if (p.cf) testo += '💳 *Codice Fiscale:* ' + p.cf + '\n';
  testo += '📍 *Indirizzo:* ' + (p.indirizzo || 'Corleto Perticara') + '\n';
  testo += '👥 *Caregiver / Referente:* ' + caregiverInfo + ' (Cell. ' + caregiverTel + ')\n\n';
  testo += '📋 *FARMACI IN ESAURIMENTO DA PRESCRIVERE:*\n' + elenco + '\n\n';
  testo += '🏥 *Farmacia per il ritiro:* ' + farmaciaNome + '\n';

  if (noteExtra) {
    testo += '\n📝 *Note e indicazioni:* ' + noteExtra + '\n';
  }

  testo += '\nLa ringraziamo sentitamente per la collaborazione.\n';
  testo += '_Data richiesta: ' + oggi + ' • Assistenza Domiciliare CareAssist Pro_';

  return testo;
}

function aggiornaAnteprimaTestoRichiesta() {
  const anteprima = document.getElementById('richiesta-anteprima-testo');
  if (anteprima) {
    anteprima.value = generaTestoRichiesta();
  }
}

function copiaTestoRichiesta() {
  const testo = generaTestoRichiesta();
  if (!testo) return;
  navigator.clipboard.writeText(testo).then(() => {
    showToast('Testo della richiesta copiato negli appunti! 📋');
  }).catch(() => {
    showToast('Seleziona e copia il testo manualmente.');
  });
}

function inviaRichiestaVia(canale) {
  const p = getActivePaziente();
  if (!p) return;

  const testo = generaTestoRichiesta();
  const checked = document.querySelectorAll('.chk-richiesta-farmaco:checked').length;
  if (checked === 0) {
    showToast('Seleziona almeno un farmaco da richiedere!', 'warning');
    return;
  }

  // Prepara destinatari
  const telMedico = (p.medicoTel || p.telMedico || '').replace(/[^0-9]/g, '');
  const emailMedico = p.medicoEmail || '';
  const oggettoEmail = encodeURIComponent(`Richiesta Rinnovo Prescrizioni Farmaci - ${p.nome}`);
  const corpoUrl = encodeURIComponent(testo);

  if (canale === 'whatsapp' || canale === 'entrambi') {
    let whatsappUrl = '';
    if (telMedico) {
      whatsappUrl = `https://api.whatsapp.com/send?phone=39${telMedico}&text=${corpoUrl}`;
    } else {
      whatsappUrl = `https://api.whatsapp.com/send?text=${corpoUrl}`;
    }
    window.open(whatsappUrl, '_blank');
  }

  if (canale === 'email' || canale === 'entrambi') {
    const mailtoUrl = `mailto:${emailMedico}?subject=${oggettoEmail}&body=${corpoUrl}`;
    // Apri client di posta
    setTimeout(() => {
      window.location.href = mailtoUrl;
    }, canale === 'entrambi' ? 600 : 0);
  }

  // Registra l'evento di richiesta nel diario
  p.registrazioni.push({
    id: 'log_' + Date.now(),
    tipo: 'richiesta_medico',
    timestamp: new Date().toISOString(),
    desc: `Richiesta Prescrizioni Farmaci inoltrata al Medico Curante via ${canale.toUpperCase()} (${checked} farmaci richiesti). Farmacia: ${p.farmaciaDiRiferimento || 'Farmacia MACARIO'}.`,
    operatore: 'Operatore OSS / Assistenza'
  });

  saveDb();
  showToast(`Richiesta farmaci inviata con successo via ${canale.toUpperCase()}! 🚀`);
  closeModal('modal-richiesta-medico');
}

async function eliminaTerapia(id) {
  const p = getActivePaziente();
  if (!p || !p.terapie) return;
  const t = p.terapie.find(x => String(x.id) === String(id) || x.id == id);
  if (!t) {
    console.warn('eliminaTerapia: farmaco non trovato per id', id);
    return;
  }

  let ok = false;
  if (typeof customConfirm === 'function') {
    ok = await customConfirm(
      'Elimina Farmaco',
      'Vuoi eliminare "' + t.farmaco + '" dal piano terapeutico di ' + (p.nome || 'questo assistito') + '?' + (typeof CESTINO_AVVISO !== 'undefined' ? CESTINO_AVVISO : ''),
      '🗑️',
      'Sposta nel Cestino'
    );
  } else {
    ok = confirm('Vuoi eliminare "' + t.farmaco + '" dal piano terapeutico di ' + (p.nome || 'questo assistito') + '?');
  }

  if (ok) {
    var backupItem = JSON.parse(JSON.stringify(t));
    var cestinoId = null;
    if (typeof cestinoAggiungi === 'function') {
      cestinoId = cestinoAggiungi('terapia', t.farmaco, (t.dosaggio || '') + (t.ora ? ' · ore ' + t.ora : ''), t, p);
    }
    p.terapie = p.terapie.filter(x => String(x.id) !== String(id) && x.id != id);
    if (typeof saveDb === 'function') saveDb();

    // RENDER IMMEDIATO DI TUTTE LE VISTE
    if (typeof renderTerapie === 'function') renderTerapie();
    if (typeof renderMobileNativeView === 'function') renderMobileNativeView();
    if (typeof renderDashboard === 'function') renderDashboard();
    if (typeof renderTerapiePreview === 'function') renderTerapiePreview();
    if (typeof aggiornaIndicatoriRitardiUI === 'function') aggiornaIndicatoriRitardiUI();
    if (typeof renderAll === 'function') renderAll();

    // CHIUDI MODALI SE APERTI
    if (typeof closeModal === 'function') {
      closeModal('modal-modifica-farmaco');
    }
    if (typeof chiudiSchedaFarmacoFullscreen === 'function') {
      chiudiSchedaFarmacoFullscreen();
    }

    if (typeof showToast === 'function') {
      showToast('Farmaco "' + t.farmaco + '" rimosso con successo e spostato nel Cestino! 🗑️', 'info');
    }

    // BANNER DI SICUREZZA FLOTTANTE "ANNULLA SUBITO" PER 12 SECONDI
    if (typeof mostraBannerAnnullaCancellazione === 'function' && cestinoId) {
      mostraBannerAnnullaCancellazione(backupItem, cestinoId);
    }
  }
}
window.eliminaTerapia = eliminaTerapia;

function eliminaFarmacoCorrenteDaModale() {
  const idEl = document.getElementById('edit-farm-id');
  const id = idEl ? idEl.value : null;
  if (!id) return;
  eliminaTerapia(id);
}
window.eliminaFarmacoCorrenteDaModale = eliminaFarmacoCorrenteDaModale;

// Rendering Registro Attività Recenti (Diario OSS) con Selezione ed Eliminazione Massiva
function getDiarioCheckboxes(scope) {
  const normScope = (scope === 'recent') ? 'diario' : (scope || 'diario');
  const selector = (normScope === 'diario')
    ? '.diario-cb-diario, .diario-cb-recent'
    : `.diario-cb-${normScope}`;
  return Array.from(document.querySelectorAll(selector));
}

function onDiarioCheckboxChange(scope) {
  const normScope = (scope === 'recent') ? 'diario' : (scope || 'diario');
  const cbs = getDiarioCheckboxes(normScope);
  const checked = cbs.filter(cb => cb.checked);
  const total = cbs.length;

  cbs.forEach(cb => {
    const tr = cb.closest('tr');
    if (tr) {
      if (cb.checked) tr.classList.add('selected-row');
      else tr.classList.remove('selected-row');
    }
  });

  const headerCb = document.getElementById(`${normScope}-select-all-cb`) || document.getElementById(`${scope}-select-all-cb`);
  if (headerCb) {
    headerCb.checked = total > 0 && checked.length === total;
    headerCb.indeterminate = checked.length > 0 && checked.length < total;
  }

  const btnText = document.getElementById(`btn-${normScope}-select-all-text`) || document.getElementById(`btn-${scope}-select-all-text`);
  const btnIcon = document.getElementById(`btn-${normScope}-select-all-icon`) || document.getElementById(`btn-${scope}-select-all-icon`);
  if (btnText && btnIcon) {
    if (total > 0 && checked.length === total) {
      btnText.textContent = 'Deseleziona Tutti';
      btnIcon.textContent = '◻️';
    } else {
      btnText.textContent = 'Seleziona Tutti';
      btnIcon.textContent = '☑️';
    }
  }

  const btnDel = document.getElementById(`btn-${normScope}-elimina-selezionati`) || document.getElementById(`btn-${scope}-elimina-selezionati`);
  const countSpan = document.getElementById(`${normScope}-selected-count`) || document.getElementById(`${scope}-selected-count`);
  if (btnDel) {
    if (checked.length > 0) {
      btnDel.style.display = 'inline-flex';
      if (countSpan) countSpan.textContent = checked.length;
    } else {
      btnDel.style.display = 'none';
      if (countSpan) countSpan.textContent = '0';
    }
  }
}

function toggleSelectAllDiario(isChecked, scope) {
  const normScope = (scope === 'recent') ? 'diario' : (scope || 'diario');
  const cbs = getDiarioCheckboxes(normScope);
  cbs.forEach(cb => {
    cb.checked = isChecked;
  });
  onDiarioCheckboxChange(normScope);
}

function toggleSelectAllDiarioBtn(scope) {
  const normScope = (scope === 'recent') ? 'diario' : (scope || 'diario');
  const cbs = getDiarioCheckboxes(normScope);
  if (!cbs.length) return;
  const anyUnchecked = cbs.some(cb => !cb.checked);
  toggleSelectAllDiario(anyUnchecked, normScope);
}

async function eliminaAnnotazioniSelezionate(scope) {
  const p = getActivePaziente();
  if (!p) return;

  const cbs = Array.from(document.querySelectorAll('.diario-cb-diario:checked, .diario-cb-recent:checked, .diario-cb-full:checked'));
  const count = cbs.length;
  if (!count) {
    showToast('Nessuna annotazione selezionata.', 'warning');
    return;
  }

  const scelta = await window.chiediTipoEliminazioneDiario(count, p.nome);
  if (!scelta) return;

  const idsToDelete = new Set(cbs.map(cb => String(cb.dataset.id)));
  const daArchiviare = (p.registrazioni || []).filter(r => idsToDelete.has(String(r.id)));

  if (scelta === 'cestino') {
    if (daArchiviare.length && typeof cestinoAggiungi === 'function') {
      try {
        cestinoAggiungi('annotazione', daArchiviare.length + ' annotazioni del diario', (daArchiviare[0].desc || daArchiviare[0].tipo || '').toString().slice(0, 110), daArchiviare, p);
      } catch (err) { }
    }
    showToast(`${count} annotazioni spostate nel Cestino. 📦`, 'info');
  } else if (scelta === 'definitivo') {
    showToast(`${count} annotazioni eliminate definitivamente per sempre. ⛔`, 'success');
  }

  p.registrazioni = (p.registrazioni || []).filter(r => !idsToDelete.has(String(r.id)));
  saveDb();
  renderDiario();
  if (typeof renderDiarioMobile === 'function') renderDiarioMobile();
}
window.eliminaAnnotazioniSelezionate = eliminaAnnotazioniSelezionate;

function renderDiario() {
  const p = getActivePaziente();
  const container = document.getElementById('diario-table-body');
  const fullContainer = document.getElementById('diario-full-table-body');
  if (!container || !p) return;

  const sorted = [...(p.registrazioni || [])].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  if (!sorted.length) {
    const emptyHtml = '<tr><td colspan="6" style="text-align:center; color:#94a3b8; padding:20px;">Nessuna registrazione recente per questo paziente.</td></tr>';
    container.innerHTML = emptyHtml;
    if (fullContainer) fullContainer.innerHTML = emptyHtml;
    onDiarioCheckboxChange('diario');
    onDiarioCheckboxChange('full');
    return;
  }

  const renderRows = (list, scope) => list.map(r => {
    let icon = '📝';
    let badge = 'badge-primary';
    let desc = '';

    if (r.tipo === 'alvo') {
      icon = '💩';
      badge = 'badge-warning';
      desc = `Evacuazione: <b>${r.consistenza}</b> ${r.clisma ? '(con clisma/lassativo)' : ''} - Note: ${r.note || 'Regolare'}`;
    } else if (r.tipo === 'parametri') {
      icon = '❤️';
      badge = 'badge-success';
      desc = `PA: <b>${r.pa_max}/${r.pa_min} mmHg</b> | FC: <b>${r.fc} bpm</b> | SpO2: <b>${r.spo2}%</b> | Temp: <b>${r.temp}°C</b>`;
      if (r.glicemia) {
        const gVal = parseFloat(r.glicemia);
        let gBadge = '#1e40af';
        let gAlert = '';
        if (gVal < 70) { gBadge = '#dc2626'; gAlert = ' ⚠️ IPOGLICEMIA!'; }
        else if (gVal > 200) { gBadge = '#ea580c'; gAlert = ' ⚠️ IPERGLICEMIA!'; }
        desc += ` | Glicemia: <b style="color:${gBadge};">${r.glicemia} mg/dl${gAlert}</b>`;
      }
      if (r.temp >= 37.5 || (r.glicemia && (parseFloat(r.glicemia) < 70 || parseFloat(r.glicemia) > 200))) badge = 'badge-danger';
    } else if (r.tipo === 'postura') {
      icon = '🔄';
      badge = 'badge-primary';
      desc = `Cambio Postura: <b>${r.posizione}</b> | Cute: <b>${r.cute || 'Integra'}</b>`;
    } else if (r.tipo === 'idratazione') {
      icon = '💧';
      badge = 'badge-primary';
      desc = `Idratazione: <b>+${r.ml} ml</b> (${r.bevanda}) &rarr; Totale oggi: <b>${r.totaleGiorno || ''} ml</b>`;
    } else if (r.tipo === 'diuresi') {
      icon = '🧪';
      badge = 'badge-warning';
      desc = `Diuresi [${r.raccolta}]: <b>${r.volume}</b> | Aspetto: <b>${r.aspetto}</b> ${r.note ? `| Note: <i>${r.note}</i>` : ''}`;
    } else if (r.tipo === 'glicemia') {
      icon = '🩸';
      const valG = parseFloat(r.valore) || 0;
      badge = valG < 70 ? 'badge-danger' : (valG > 200 ? 'badge-warning' : 'badge-primary');
      desc = `Glicemia: <b>${r.valore} mg/dl</b> [${r.momento}] ${r.insulina ? `| Insulina: <b>${r.insulina} UI</b>` : ''} ${r.note ? `| Note: <i>${r.note}</i>` : ''}`;
    } else if (r.tipo === 'pasto') {
      icon = '🍲';
      badge = 'badge-success';
      desc = `Nutrizione [${r.pasto}]: Assunto <b>${r.quantita}</b> | Dettaglio: <i>${r.alimenti}</i>`;
    } else if (r.tipo === 'braden') {
      icon = '🎯';
      badge = 'badge-primary';
      desc = `Valutazione Scala di Braden: Punteggio <b>${r.score}/23</b> &rarr; <b>${r.fascia}</b>`;
    } else if (r.tipo === 'caduta') {
      icon = '⚠️';
      badge = 'badge-danger';
      desc = `<b>INCIDENT CADUTA:</b> ${r.dinamica} | Coscienza: <b>${r.coscienza}</b> | Esito: <b>${r.esito}</b> | Azioni: <i>${r.azioni}</i>`;
    } else if (r.tipo === 'consegna') {
      icon = '📋';
      badge = 'badge-success';
      desc = `<b>Consegna di Turno Generata</b> | Condivisa per continuità assistenziale`;
    } else if (r.tipo === 'consegna_vocale') {
      icon = '🎙️';
      badge = 'badge-primary';
      const playBtn = r.audioData ? `<audio src="${r.audioData}" controls style="height:26px; vertical-align:middle; margin-left:6px; max-width:200px;"></audio>` : '';
      const chips = r.parametriEstratti ? `<div style="display:flex; gap:4px; margin-top:4px; flex-wrap:wrap;">${r.parametriEstratti}</div>` : '';
      desc = `<b style="color:#4f46e5;">CONSEGNA VOCALE AI:</b> <i>"${r.testo || ''}"</i> ${playBtn} ${chips}`;
    } else if (r.tipo === 'farmaco') {
      icon = '💊';
      badge = 'badge-success';
      desc = `Somministrato: <b>${r.farmaco}</b> (${r.dosaggio}) &rarr; <small style="color:#059669;">1 compressa scalata dalla scorta</small>`;
    } else if (r.tipo === 'farmaco_ritardo') {
      icon = '⚠️';
      badge = 'badge-danger';
      const rOre = Math.floor((r.minutiRitardo || 0) / 60);
      const rMin = (r.minutiRitardo || 0) % 60;
      const ritardoStr = rOre > 0 ? `${rOre}h ${rMin}m` : `${rMin} min`;
      desc = `<b style="color:#dc2626;">RITARDO SOMMINISTRAZIONE:</b> <b>${r.farmaco}</b> (${r.dosaggio}) &rarr; <span class="badge badge-danger" style="background:#dc2626; font-size:11px; padding:2px 7px;">+${ritardoStr} di ritardo</span> (Previsto ore <b>${r.orarioPrevisto || ''}</b> &bull; Dato alle <b>${r.orarioReale || ''}</b>)`;
    } else if (r.tipo === 'farmaco_saltato') {
      icon = '❌';
      badge = 'badge-danger';
      desc = `<b style="color:#b91c1c;">TERAPIA NON ASSUNTA / SALTATA:</b> <b>${r.farmaco}</b> (${r.dosaggio}) &rarr; Motivo: <b style="color:#991b1b;">${r.motivo || 'Non specificato'}</b> ${r.note ? `<i>(${r.note})</i>` : ''} <small style="color:#64748b;">[Previsto ore ${r.orarioPrevisto || ''} - Scorta non scalata]</small>`;
    } else if (r.tipo === 'farmaco_annullato') {
      icon = '↩️';
      badge = 'badge-warning';
      desc = `Rettifica Terapia: <b>${r.farmaco}</b> &rarr; <small style="color:#d97706;">Somministrazione annullata (+1 cpr restituita)</small>`;
    } else if (r.tipo === 'scorta') {
      icon = '📦';
      badge = 'badge-primary';
      desc = `<b>${r.desc}</b>`;
    } else if (r.tipo === 'nota_turno') {
      icon = '📝';
      badge = 'badge-success';
      desc = `<b style="color:#0369a1;">NOTA DI TURNO:</b> <i>"${r.testo || ''}"</i>`;
    }

    const d = new Date(r.timestamp);
    const dataStr = `${d.toLocaleDateString('it-IT')} ${d.toLocaleTimeString('it-IT', { hour: '2-digit', minute: '2-digit' })}`;

    return `
      <tr id="diario-row-${scope}-${r.id}">
        <td class="table-checkbox-cell" style="text-align:center; cursor:pointer;" onclick="if(event.target.tagName!=='INPUT'){const cb=this.querySelector('input');if(cb){cb.checked=!cb.checked;onDiarioCheckboxChange('${scope}');}}">
          <input type="checkbox" class="diario-cb-${scope}" data-id="${r.id}" onchange="onDiarioCheckboxChange('${scope}')" title="Seleziona riga">
        </td>
        <td><b>${dataStr}</b></td>
        <td><span class="badge ${badge}">${icon} ${r.tipo.toUpperCase()}</span></td>
        <td>${desc}</td>
        <td><small>${r.operatore || 'Caregiver'}</small></td>
        <td style="text-align:center;"><button class="btn-delete-row-diario" onclick="eliminaLog('${r.id}')" title="Elimina questa annotazione">✕</button></td>
      </tr>
    `;
  }).join('');

  container.innerHTML = renderRows(sorted.slice(0, 10), 'diario');
  if (fullContainer) fullContainer.innerHTML = renderRows(sorted, 'full');

  onDiarioCheckboxChange('diario');
  onDiarioCheckboxChange('full');
}

async function eliminaLog(id) {
  const p = getActivePaziente();
  if (!p) return;

  const scelta = await window.chiediTipoEliminazioneDiario(1, p.nome);
  if (!scelta) return;

  const rec = (p.registrazioni || []).find(r => String(r.id) === String(id) || String(r.timestamp) === String(id));
  if (!rec) return;

  if (scelta === 'cestino') {
    if (typeof cestinoAggiungi === 'function') {
      cestinoAggiungi('annotazione', 'Annotazione del diario', (rec.testo || rec.desc || rec.tipo || '').toString().slice(0, 140), [rec], p);
    }
    showToast('Registrazione spostata nel Cestino. 📦', 'info');
  } else if (scelta === 'definitivo') {
    showToast('Registrazione eliminata definitivamente per sempre. ⛔', 'success');
  }

  p.registrazioni = (p.registrazioni || []).filter(r => String(r.id) !== String(id) && String(r.timestamp) !== String(id));
  saveDb();
  renderDiario();
  if (typeof renderDiarioMobile === 'function') renderDiarioMobile();
}
window.eliminaLog = eliminaLog;

async function svuotaRitardiFarmaci() {
  const authAdmin = await window.richiediPinAdminPerCancellazione('Inserisci il PIN o Password Amministratore per cancellare gli avvisi di ritardo:');
  if (!authAdmin) {
    showToast('Operazione annullata: autorizzazione Admin non fornita.', 'warning');
    return;
  }
  const p = getActivePaziente();
  if (!p) return;

  const ritardi = (p.registrazioni || []).filter(r => r.tipo === 'farmaco_ritardo');
  if (ritardi.length === 0) {
    showToast('Nessun avviso di ritardo presente nel registro.', 'info');
    return;
  }

  let ok = false;
  try {
    ok = await customConfirm(
      'Cancella Avvisi di Ritardo',
      'Vuoi cancellare tutti i ' + ritardi.length + ' avvisi di ritardo registrati per ' + p.nome + '?' + CESTINO_AVVISO,
      '🧹',
      'Sposta nel Cestino'
    );
  } catch (e) {
    ok = confirm('Vuoi cancellare tutti i ' + ritardi.length + ' avvisi di ritardo registrati?');
  }

  if (ok) {
    cestinoAggiungi('annotazione', ritardi.length + ' avvisi di ritardo farmaci', 'Registro ritardi di ' + p.nome, ritardi, p);
    p.registrazioni = (p.registrazioni || []).filter(r => r.tipo !== 'farmaco_ritardo');
    saveDb();
    renderDiario();
    showToast('I ' + ritardi.length + ' avvisi di ritardo sono nel Cestino. 🧹');
  }
}
window.svuotaRitardiFarmaci = svuotaRitardiFarmaci;

// Rendering Visite Mediche
function renderVisite() {
  const p = getActivePaziente();
  const container = document.getElementById('visite-table-body');
  const preview = document.getElementById('visite-preview-body');
  if (!container || !p) return;

  if (!p.visite || !p.visite.length) {
    const emptyHtml = '<tr><td colspan="5" style="text-align:center; color:#94a3b8; padding:16px;">Nessuna visita o appuntamento in programma.</td></tr>';
    container.innerHTML = emptyHtml;
    if (preview) preview.innerHTML = '<tr><td colspan="5" style="text-align:center; color:#94a3b8;">Nessun appuntamento imminente.</td></tr>';
    return;
  }

  container.innerHTML = p.visite.map(v => {
    const isFatto = v.fatto || v.statoVisita === 'Eseguita';
    const isPosticipata = v.statoVisita === 'Posticipata / Spostata';
    const isDisdetta = v.statoVisita === 'Disdetta';

    let badgeStato = '';
    if (isFatto) {
      badgeStato = '<span class="badge badge-success">✓ Eseguita</span>';
    } else if (isPosticipata) {
      badgeStato = '<span class="badge badge-warning" style="background:#fef3c7; color:#b45309; border:1px solid #fde047;">🔄 Posticipata</span>';
    } else if (isDisdetta) {
      badgeStato = '<span class="badge badge-danger">❌ Disdetta</span>';
    } else {
      badgeStato = '<span class="badge badge-warning">⏳ In attesa</span>';
    }

    const dStr = (v.data && v.data.length >= 10) ? (v.data.slice(8, 10) + '/' + v.data.slice(5, 7) + '/' + v.data.slice(0, 4)) : v.data;

    return `
      <tr style="background:${isPosticipata ? '#fffbeb' : ''};">
        <td>
          <b>${dStr}</b> ore ${v.ora || '10:00'}
          ${isPosticipata ? `<div style="font-size:10.5px; color:#b45309; margin-top:2px;">🔄 Ex: <b>${v.dataPrecedente || '--'}</b></div>` : ''}
        </td>
        <td>
          <div style="font-weight:800; color:#0f172a;">${v.medico || 'Specialista'}</div>
          ${v.tipoStruttura ? `<div style="font-size:11px; color:#0369a1; font-weight:700;">${v.tipoStruttura}</div>` : ''}
          ${v.luogo ? `<div style="font-size:10.5px; color:#64748b;">📍 ${v.luogo}</div>` : ''}
          ${v.telefono ? `<div style="font-size:11px; margin-top:2px;"><a href="tel:${v.telefono.replace(/\s+/g, '')}" style="color:#059669; font-weight:800; text-decoration:none;">📞 ${v.telefono}</a></div>` : ''}
        </td>
        <td>
          <div style="font-weight:700; color:#1e293b;">${v.motivo || 'Controllo periodico'}</div>
          ${v.impegnativa ? `<div style="font-size:11px; color:#047857; margin-top:2px;">📑 ${v.impegnativa}${v.codiceNre ? ' (' + v.codiceNre + ')' : ''}</div>` : ''}
          ${v.preparazione && v.preparazione !== 'Nessuna preparazione speciale richiesta' ? `<div style="font-size:11px; color:#be123c; background:#ffe4e6; padding:2px 6px; border-radius:4px; display:inline-block; margin-top:3px; font-weight:700;">⚠️ ${v.preparazione}</div>` : ''}
          ${v.trasporto && !v.trasporto.includes('Nessun') ? `<div style="font-size:10.5px; color:#475569; margin-top:2px;">🚑 ${v.trasporto}</div>` : ''}
        </td>
        <td>${badgeStato}</td>
        <td style="white-space:nowrap;">
          <button class="btn btn-outline" style="padding:4px 8px; font-size:11px; margin-right:4px; border-color:#fde047; color:#854d0e; font-weight:800; background:#fffbeb;" onclick="posticipaRapidoVisita(${v.id})" title="Posticipa o sposta la data della visita">
            🔄 Posticipa
          </button>
          <button class="btn btn-outline" style="padding:4px 8px; font-size:11px; margin-right:4px; border-color:#38bdf8; color:#0284c7; font-weight:800;" onclick="apriModificaVisita(${v.id})" title="Modifica tutti i campi della visita">
            ✏️ Modifica
          </button>
          <button class="btn ${isFatto ? 'btn-outline' : 'btn-success'}" style="padding:4px 8px; font-size:11px; margin-right:4px;" onclick="toggleVisita(${v.id})">
            ${isFatto ? 'Riapri' : '✓ Fatto'}
          </button>
          <button class="btn btn-outline" style="padding:4px 8px; font-size:11px;" onclick="eliminaVisita(${v.id})" title="Sposta nel Cestino">🗑️</button>
        </td>
      </tr>
    `;
  }).join('');

  if (preview) {
    preview.innerHTML = p.visite.slice(0, 4).map(v => {
      const isFatto = v.fatto || v.statoVisita === 'Eseguita';
      const isPosticipata = v.statoVisita === 'Posticipata / Spostata';
      const dStr = (v.data && v.data.length >= 10) ? (v.data.slice(8, 10) + '/' + v.data.slice(5, 7) + '/' + v.data.slice(0, 4)) : v.data;
      return `
        <tr style="background:${isPosticipata ? '#fffbeb' : ''};">
          <td>
            <b>${dStr}</b>${v.ora ? `<div style="font-size:11px; color:#0284c7; font-weight:700;">ore ${v.ora}</div>` : ''}
            ${isPosticipata ? '<div style="font-size:9.5px; color:#b45309; font-weight:800;">🔄 Posticipata</div>' : ''}
          </td>
          <td>
            <b>${v.medico}</b>
            ${v.tipoStruttura ? `<div style="font-size:10px; color:#64748b;">${v.tipoStruttura}</div>` : ''}
            ${v.telefono ? `<div style="font-size:10px; color:#059669; font-weight:700;">📞 ${v.telefono}</div>` : ''}
          </td>
          <td>${v.motivo}</td>
          <td><span class="badge ${isFatto ? 'badge-success' : (isPosticipata ? 'badge-warning' : 'badge-warning')}">${isFatto ? 'Fatto' : (isPosticipata ? 'Posticipata' : 'In attesa')}</span></td>
          <td style="white-space:nowrap;">
            <button type="button" class="btn btn-outline" style="padding:4px 9px; font-size:11.5px; margin-right:4px; border-color:#38bdf8; background:#eff6ff; color:#0284c7; font-weight:800; cursor:pointer;" onclick="apriModificaVisita(${v.id})" title="Modifica tutti i dati della visita specialistica">
              ✏️ Modifica
            </button>
            <button type="button" class="btn btn-outline" style="padding:4px 8px; font-size:11px; margin-right:4px; border-color:#fde047; background:#fffbeb; color:#854d0e; font-weight:800; cursor:pointer;" onclick="posticipaRapidoVisita(${v.id})" title="Posticipa o sposta la data della visita">
              🔄
            </button>
            <button type="button" class="btn btn-outline" style="padding:4px 7px; font-size:11px; cursor:pointer;" onclick="eliminaVisita(${v.id})" title="Sposta nel Cestino">
              🗑️
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }
}

function toggleVisita(id) {
  const p = getActivePaziente();
  if (!p) return;
  const v = (p.visite || []).find(item => String(item.id) === String(id));
  if (v) {
    v.fatto = !v.fatto;
    saveDb();
    if (typeof renderMobileNativeView === 'function') renderMobileNativeView();
    if (typeof renderVisite === 'function') renderVisite();
    var modalMev = document.getElementById('modal-elenco-visite');
    if (modalMev && modalMev.style.display === 'flex' && typeof renderElencoVisiteBody === 'function') {
      renderElencoVisiteBody();
    }
    if (typeof showToast === 'function') showToast(v.fatto ? 'Visita segnata come Eseguita! ✓' : 'Visita riaperta in programma ⏳');
  }
}

async function eliminaVisita(id) {
  const p = getActivePaziente();
  if (!p) return;
  const v = (p.visite || []).find(x => String(x.id) === String(id));
  if (!v) return;
  const ok = await customConfirm(
    'Elimina Appuntamento',
    'Vuoi cancellare la visita "' + (v.medico || '') + ' - ' + (v.motivo || '') + '"?' + CESTINO_AVVISO,
    '📅',
    'Sposta nel Cestino'
  );
  if (ok) {
    cestinoAggiungi('visita', (v.medico || 'Visita') + (v.motivo ? ' - ' + v.motivo : ''), (v.data ? new Date(v.data).toLocaleDateString('it-IT') : '') + (v.ora ? ' ore ' + v.ora : ''), v, p);
    p.visite = p.visite.filter(x => String(x.id) !== String(id));
    saveDb();
    if (typeof renderMobileNativeView === 'function') renderMobileNativeView();
    if (typeof renderVisite === 'function') renderVisite();
    var modalMev = document.getElementById('modal-elenco-visite');
    if (modalMev && modalMev.style.display === 'flex' && typeof renderElencoVisiteBody === 'function') {
      renderElencoVisiteBody();
    }
    showToast('Appuntamento spostato nel Cestino. 📅');
  }
}

function apriModificaVisita(id) {
  const p = getActivePaziente();
  if (!p || !p.visite) return;
  const v = p.visite.find(x => String(x.id) === String(id));
  if (!v) {
    if (typeof showToast === 'function') showToast('⚠️ Visita non trovata');
    return;
  }
  window._inModificaVisita = true;
  openModal('modal-visita');

  const editIdEl = document.getElementById('vis-edit-id');
  const titleEl = document.getElementById('modal-visita-title');
  const btnEl = document.getElementById('btn-salva-visita');
  const dateEl = document.getElementById('vis-data');
  const oraEl = document.getElementById('vis-ora');
  const statoEl = document.getElementById('vis-stato');
  const dataPrecEl = document.getElementById('vis-data-precedente');
  const motSpostEl = document.getElementById('vis-motivo-spostamento');
  const medEl = document.getElementById('vis-medico');
  const strEl = document.getElementById('vis-tipo-struttura');
  const luogoEl = document.getElementById('vis-luogo');
  const telEl = document.getElementById('vis-telefono');
  const impEl = document.getElementById('vis-impegnativa');
  const nreEl = document.getElementById('vis-nre');
  const prioEl = document.getElementById('vis-priorita');
  const traspEl = document.getElementById('vis-trasporto');
  const motEl = document.getElementById('vis-motivo');
  const prepEl = document.getElementById('vis-preparazione');
  const docEl = document.getElementById('vis-documenti');
  const percEl = document.getElementById('vis-percorso');

  if (editIdEl) editIdEl.value = v.id;
  if (titleEl) titleEl.innerHTML = '✏️ Modifica Visita o Prestazione';
  if (btnEl) btnEl.innerHTML = '💾 Salva Modifiche';

  if (dateEl) dateEl.value = v.data ? v.data.slice(0, 10) : '';
  if (oraEl) oraEl.value = v.ora || '10:00';

  const st = v.statoVisita || (v.fatto ? 'Eseguita' : 'In programma');
  if (statoEl) {
    statoEl.value = st;
    gestisciCambioStatoVisita(st);
  }
  if (dataPrecEl) dataPrecEl.value = v.dataPrecedente || '';
  if (motSpostEl) motSpostEl.value = v.motivoSpostamento || '';

  if (medEl) medEl.value = v.medico || '';
  if (strEl) strEl.value = v.tipoStruttura || 'ASL / Poliambulatorio CUP';
  if (luogoEl) luogoEl.value = v.luogo || '';
  if (telEl) telEl.value = v.telefono || '';
  if (percEl) percEl.value = v.comeRaggiungere || '';

  if (impEl) impEl.value = v.impegnativa || 'Ricetta NRE Presente';
  if (nreEl) nreEl.value = v.codiceNre || '';
  if (prioEl) prioEl.value = v.priorita || 'P - Programmata (180 gg)';
  if (traspEl) traspEl.value = v.trasporto || 'Autonomo / Deambulante';

  if (motEl) motEl.value = v.motivo || '';
  if (prepEl) prepEl.value = v.preparazione || '';
  if (docEl) docEl.value = v.documenti || "Tessera Sanitaria, Documento d'Identità, Esenzione Ticket, Piano Terapeutico";
  if (typeof popolaSelettoreVisiteEsistenti === 'function') {
    popolaSelettoreVisiteEsistenti(v.id);
  }
  if (typeof controllaConflittiVisita === "function") {
    setTimeout(controllaConflittiVisita, 30);
  }
}
window.apriModificaVisita = apriModificaVisita;

// Gestione Modali
function openModal(id) {
  if (id === 'modal-farmaco') return apriMascheraNuovoFarmaco();
  const el = document.getElementById(id);
  if (el) {
    el.classList.add('active');
    el.style.display = 'flex';

    if (id === 'modal-visita' && !window._inModificaVisita) {
      const editIdEl = document.getElementById('vis-edit-id');
      const titleEl = document.getElementById('modal-visita-title');
      const btnEl = document.getElementById('btn-salva-visita');
      const dateEl = document.getElementById('vis-data');
      const oraEl = document.getElementById('vis-ora');
      const statoEl = document.getElementById('vis-stato');
      const dataPrecEl = document.getElementById('vis-data-precedente');
      const motSpostEl = document.getElementById('vis-motivo-spostamento');
      const medEl = document.getElementById('vis-medico');
      const strEl = document.getElementById('vis-tipo-struttura');
      const luogoEl = document.getElementById('vis-luogo');
      const telEl = document.getElementById('vis-telefono');
      const impEl = document.getElementById('vis-impegnativa');
      const nreEl = document.getElementById('vis-nre');
      const prioEl = document.getElementById('vis-priorita');
      const traspEl = document.getElementById('vis-trasporto');
      const motEl = document.getElementById('vis-motivo');
      const prepEl = document.getElementById('vis-preparazione');
      const docEl = document.getElementById('vis-documenti');
      const percEl = document.getElementById('vis-percorso');

      if (editIdEl) editIdEl.value = '';
      if (titleEl) titleEl.innerHTML = '📅 Pianifica Visita o Prestazione';
      if (btnEl) btnEl.innerHTML = '💾 Salva Appuntamento';
      if (dateEl) dateEl.value = new Date().toISOString().slice(0, 10);
      if (oraEl) oraEl.value = '10:00';
      if (statoEl) {
        statoEl.value = 'In programma';
        gestisciCambioStatoVisita('In programma');
      }
      if (dataPrecEl) dataPrecEl.value = '';
      if (motSpostEl) motSpostEl.value = '';
      if (medEl) medEl.value = '';
      if (strEl) strEl.value = 'ASL / Poliambulatorio CUP';
      if (luogoEl) luogoEl.value = '';
      if (telEl) telEl.value = '';
      if (percEl) percEl.value = '';
      if (impEl) impEl.value = 'Ricetta NRE Presente';
      if (nreEl) nreEl.value = '';
      if (prioEl) prioEl.value = 'P - Programmata (180 gg)';
      if (traspEl) traspEl.value = 'Autonomo / Deambulante';
      if (motEl) motEl.value = '';
      if (prepEl) prepEl.value = '';
      if (docEl) docEl.value = "Tessera Sanitaria, Documento d'Identità, Esenzione Ticket, Piano Terapeutico";
    }

    // Inietta o aggiorna in automatico l'indicazione chiara del paziente attivo
    const p = getActivePaziente();
    if (p && id !== 'modal-nuovo-paziente' && id !== 'modal-cestino' && id !== 'modal-report-whatsapp' && id !== 'modal-scheda-118' && id !== 'modal-modifica-farmaco' && id !== 'modal-laboratorio-scotti' && id !== 'modal-archivio-storico-controlli' && id !== 'modal-diario-mobile' && id !== 'modal-modifica-diario-item' && id !== 'modal-guida-contestuale' && id !== 'modal-briefing-vocale') {
      const header = el.querySelector('.modal-header');
      if (header) {
        // Cerca o crea il badge del paziente all'interno di .modal-title (layout a 2 righe pulito, zero sovrapposizioni)
        let badge = header.querySelector('.modal-patient-badge');
        const titleEl = header.querySelector('.modal-title');
        if (!badge) {
          badge = document.createElement('div');
          badge.className = 'modal-patient-badge';
          badge.style.marginTop = '4px';
        }
        if (titleEl) {
          titleEl.appendChild(badge);
        } else {
          header.appendChild(badge);
        }
        badge.innerHTML = `👤 Assistito: <b>${p.nome}</b>`;
        badge.title = `Stai operando sulla cartella clinica di ${p.nome}`;
      }
    }

    if (id === 'modal-visita') {
      if (typeof popolaSelettoreVisiteEsistenti === 'function') {
        popolaSelettoreVisiteEsistenti('');
      }
      var ocrSt = document.getElementById('vis-ocr-status'); if (ocrSt) ocrSt.style.display = 'none';
      var aiBox = document.getElementById('vis-box-suggerimenti-ai'); if (aiBox) aiBox.style.display = 'none';
      var ocrIn = document.getElementById('vis-ocr-input'); if (ocrIn) ocrIn.value = '';
      var patEl = getActivePaziente();
      if (patEl && patEl.allettato && !window._inModificaVisita) {
        var trEl = document.getElementById('vis-trasporto');
        if (trEl) trEl.value = 'Ambulanza / Trasporto Sanitario';
      }
      if (typeof controllaConflittiVisita === 'function') {
        setTimeout(controllaConflittiVisita, 40);
      }
      const editIdEl = document.getElementById('vis-edit-id');
      const titleEl = document.getElementById('modal-visita-title');
      const btnEl = document.getElementById('btn-salva-visita');
      if (!window._inModificaVisita) {
        if (editIdEl) editIdEl.value = '';
        if (titleEl) titleEl.innerHTML = '📅 Pianifica Visita o Prestazione';
        if (btnEl) btnEl.innerHTML = 'Salva Appuntamento';
        const visMedEl = document.getElementById('vis-medico');
        const visMotEl = document.getElementById('vis-motivo');
        const visOraEl = document.getElementById('vis-ora');
        if (visMedEl) visMedEl.value = '';
        if (visMotEl) visMotEl.value = '';
        if (visOraEl) visOraEl.value = '10:00';
        const visDateEl = document.getElementById('vis-data');
        if (visDateEl) {
          visDateEl.value = new Date().toISOString().slice(0, 10);
        }
      }
      window._inModificaVisita = false;
    }

    if (id === 'modal-nuovo-paziente') {
      popolaSelettoreDataItaliano('nuovo', '1938-05-15');
      renderCatalogoAusiliForm('container-catalogo-ausili-nuovo', []);
    }
    document.body.classList.add('modal-open');
  }
}

function closeModal(id) {
  if (id === 'modal-guida-contestuale') {
    if (typeof fermaVoceHDGlobale === 'function') fermaVoceHDGlobale();
    _isGuidaContestualeInRiproduzione = false;
  }
  const el = document.getElementById(id);
  if (el) {
    el.classList.remove('active');
    el.style.display = 'none';
  }
  setTimeout(function () {
    const anyActive = document.querySelector('.modal-overlay.active, .modal-overlay[style*="display: flex"]');
    if (!anyActive) {
      document.body.classList.remove('modal-open');
    }
  }, 40);
}

// Salvataggi dai Form Modali
function salvaAlvo(e) {
  e.preventDefault();
  const p = getActivePaziente();
  if (!p) return;
  const entry = {
    id: 'log_' + Date.now(),
    tipo: 'alvo',
    timestamp: new Date().toISOString(),
    consistenza: document.getElementById('alvo-consistenza').value,
    clisma: document.getElementById('alvo-clisma').checked,
    note: document.getElementById('alvo-note').value,
    operatore: document.getElementById('alvo-operatore').value || 'Caregiver'
  };
  p.registrazioni.push(entry);
  closeModal('modal-alvo');
  saveDb();
  if (typeof renderMobileNativeView === 'function') renderMobileNativeView();
  if (typeof renderTerapie === 'function') renderTerapie();
}

