function salvaNuovaVisita(e) {
  e.preventDefault();
  const p = getActivePaziente();
  if (!p) return;
  if (!Array.isArray(p.visite)) p.visite = [];

  const editId = (document.getElementById('vis-edit-id')?.value || '').trim();
  const dataVal = document.getElementById('vis-data')?.value || '';
  const oraVal = document.getElementById('vis-ora')?.value || '10:00';
  const statoVisitaVal = document.getElementById('vis-stato')?.value || 'In programma';
  const dataPrecedenteVal = (document.getElementById('vis-data-precedente')?.value || '').trim();
  const motivoSpostamentoVal = (document.getElementById('vis-motivo-spostamento')?.value || '').trim();
  const medicoVal = (document.getElementById('vis-medico')?.value || '').trim();
  const tipoStrutturaVal = document.getElementById('vis-tipo-struttura')?.value || 'ASL / Poliambulatorio CUP';
  const luogoVal = (document.getElementById('vis-luogo')?.value || '').trim();
  const telefonoVal = (document.getElementById('vis-telefono')?.value || '').trim();
  const impegnativaVal = document.getElementById('vis-impegnativa')?.value || 'Ricetta NRE Presente';
  const codiceNreVal = (document.getElementById('vis-nre')?.value || '').trim();
  const prioritaVal = document.getElementById('vis-priorita')?.value || 'P - Programmata (180 gg)';
  const trasportoVal = document.getElementById('vis-trasporto')?.value || 'Autonomo / Deambulante';
  const motivoVal = (document.getElementById('vis-motivo')?.value || '').trim();
  const preparazioneVal = (document.getElementById('vis-preparazione')?.value || '').trim();
  const documentiVal = (document.getElementById('vis-documenti')?.value || '').trim();
  const percorsoVal = (document.getElementById('vis-percorso')?.value || '').trim();
  const mapsUrlVal = 'https://www.google.com/maps/dir/?api=1&destination=' + encodeURIComponent(luogoVal || percorsoVal || 'Azienda Ospedaliera Regionale San Carlo Potenza Via Potito Petrone');

  const isFatto = statoVisitaVal === 'Eseguita';

  let isModifica = false;
  if (editId) {
    const existingIndex = p.visite.findIndex(x => String(x.id) === String(editId));
    if (existingIndex !== -1) {
      p.visite[existingIndex] = {
        ...p.visite[existingIndex],
        data: dataVal,
        ora: oraVal,
        statoVisita: statoVisitaVal,
        dataPrecedente: dataPrecedenteVal,
        motivoSpostamento: motivoSpostamentoVal,
        medico: medicoVal,
        tipoStruttura: tipoStrutturaVal,
        luogo: luogoVal,
        telefono: telefonoVal,
        comeRaggiungere: percorsoVal,
        mapsUrl: mapsUrlVal,
        impegnativa: impegnativaVal,
        codiceNre: codiceNreVal,
        priorita: prioritaVal,
        trasporto: trasportoVal,
        motivo: motivoVal,
        preparazione: preparazioneVal,
        documenti: documentiVal,
        fatto: isFatto
      };
      isModifica = true;
    }
  }

  if (!isModifica) {
    const v = {
      id: Date.now(),
      data: dataVal,
      ora: oraVal,
      statoVisita: statoVisitaVal,
      dataPrecedente: dataPrecedenteVal,
      motivoSpostamento: motivoSpostamentoVal,
      medico: medicoVal,
      tipoStruttura: tipoStrutturaVal,
      luogo: luogoVal,
      telefono: telefonoVal,
      comeRaggiungere: percorsoVal,
      mapsUrl: mapsUrlVal,
      impegnativa: impegnativaVal,
      codiceNre: codiceNreVal,
      priorita: prioritaVal,
      trasporto: trasportoVal,
      motivo: motivoVal,
      preparazione: preparazioneVal,
      documenti: documentiVal,
      fatto: isFatto
    };
    p.visite.push(v);
  }

  // Ordina cronologicamente le visite
  if (p.visite && p.visite.length > 1) {
    p.visite.sort((a, b) => {
      const ta = (a.data || '') + ' ' + (a.ora || '');
      const tb = (b.data || '') + ' ' + (b.ora || '');
      return ta.localeCompare(tb);
    });
  }

  const editIdEl = document.getElementById('vis-edit-id');
  if (editIdEl) editIdEl.value = '';
  closeModal('modal-visita');
  saveDb();
  if (typeof renderMobileNativeView === 'function') renderMobileNativeView();
  if (typeof renderTerapie === 'function') renderTerapie();
  if (typeof renderVisite === 'function') renderVisite();
  // Se la scheda clinica mobile è aperta, aggiorna la lista visite all'istante
  var modalScm = document.getElementById('modal-scheda-clinica-mobile');
  if (modalScm && modalScm.style.display === 'flex' && typeof apriModalSchedaClinicaMobile === 'function') {
    apriModalSchedaClinicaMobile(p.id);
  }
  // Se l'elenco completo visite è aperto, aggiornalo all'istante
  var modalMev = document.getElementById('modal-elenco-visite');
  if (modalMev && modalMev.style.display === 'flex' && typeof renderElencoVisiteBody === 'function') {
    renderElencoVisiteBody();
  }
  if (typeof showToast === 'function') {
    showToast(isModifica ? '✏️ Visita modificata con successo!' : '📅 Visita per ' + (p.nome || 'assistito') + ' salvata con successo!');
  }
}

// Backup & Reset Multi-Paziente
function esportaBackup() {
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(AppData, null, 2));
  const dlAnchor = document.createElement('a');
  dlAnchor.setAttribute("href", dataStr);
  dlAnchor.setAttribute("download", `CareAssist_MultiPaziente_Backup_${new Date().toISOString().slice(0, 10)}.json`);
  dlAnchor.click();
}

function importaBackup(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function (e) {
    try {
      const parsed = JSON.parse(e.target.result);
      if (parsed.pazienti) {
        AppData = parsed;
      }
      saveDb();
      showToast('Backup ripristinato con successo!');
    } catch (err) {
      showToast('Errore nel file di backup JSON!', 'error');
    }
  };
  reader.readAsText(file);
}

