// GESTIONE BARRA STICKY CONTESTO ASSISTITO & SWITCH RAPIDO SENZA SCROLL
// ==========================================================================
var modalAllarmeApertoManualmente = false;

function calcolaTerapieInRitardoGlobali() {
  if (!AppData || !AppData.pazienti) return [];
  const listaPazienti = typeof getPazientiAccessibili === 'function' ? getPazientiAccessibili() : AppData.pazienti;
  const pazientiConRitardi = [];
  listaPazienti.forEach(p => {
    const terapieInRitardo = (p.terapie || []).filter(t => isTerapiaPrevistaOggi(t) && !t.fattoOggi && !t.saltatoOggi && verificaStatoOrarioFarmaco(t.ora).inRitardo);
    if (terapieInRitardo.length > 0) {
      pazientiConRitardi.push({
        paziente: p,
        farmaci: terapieInRitardo
      });
    }
  });
  return pazientiConRitardi;
}

function aggiornaIndicatoriRitardiUI(totRitardi) {
  // 1. Mobile Header Pill
  const btnMhdr = document.getElementById('mobile-header-ritardi-btn');
  const badgeMhdr = document.getElementById('mobile-header-ritardi-badge');
  if (btnMhdr) {
    if (totRitardi > 0) {
      btnMhdr.classList.add('has-delays');
      if (badgeMhdr) {
        badgeMhdr.textContent = totRitardi;
        badgeMhdr.style.display = 'inline-block';
      }
    } else {
      btnMhdr.classList.remove('has-delays');
      if (badgeMhdr) {
        badgeMhdr.textContent = '0';
        badgeMhdr.style.display = 'none';
      }
    }
  }

  // 2. Mobile Bottom Bar Tab
  const badgeMbar = document.getElementById('mbar-ritardi-badge');
  if (badgeMbar) {
    if (totRitardi > 0) {
      badgeMbar.textContent = totRitardi;
      badgeMbar.style.display = 'inline-block';
    } else {
      badgeMbar.textContent = '0';
      badgeMbar.style.display = 'none';
    }
  }

  // 3. Mobile Hero Action Card Alert Banner
  const bannerMhero = document.getElementById('mobile-hero-ritardi-banner');
  const countMhero = document.getElementById('mhero-ritardi-count');
  if (bannerMhero) {
    if (totRitardi > 0) {
      if (countMhero) countMhero.textContent = totRitardi;
      bannerMhero.style.display = 'flex';
    } else {
      bannerMhero.style.display = 'none';
    }
  }
}

function apriAllarmiTerapieManuale() {
  modalAllarmeApertoManualmente = true;
  allarmeTerapieSnoozeFinoA = 0; // reset snooze per permettere immediata consultazione

  const pazientiConRitardi = calcolaTerapieInRitardoGlobali();
  const totRitardi = pazientiConRitardi.reduce((sum, it) => sum + it.farmaci.length, 0);
  aggiornaIndicatoriRitardiUI(totRitardi);

  const modalAllarme = document.getElementById('modal-allarme-terapie');
  const listaContainer = document.getElementById('lista-pazienti-terapie-ritardo');

  if (pazientiConRitardi.length > 0) {
    controllaTerapieGlobaliTuttiPazienti();
  } else {
    if (listaContainer) {
      listaContainer.innerHTML = `
        <div style="text-align:center; padding:32px 18px; background:#f0fdf4; border:2px dashed #86efac; border-radius:18px; margin:6px 0;">
          <div style="font-size:46px; margin-bottom:10px;">🎉</div>
          <div style="font-size:18px; font-weight:900; color:#166534; margin-bottom:4px;">Nessuna Terapia in Ritardo!</div>
          <div style="font-size:13px; color:#15803d; line-height:1.4; max-width:380px; margin:0 auto;">
            Tutti i farmaci previsti fino ad ora sono stati regolarmente somministrati oppure non sono ancora scaduti per tutti gli assistiti.
          </div>
          <div style="margin-top:16px;">
            <button type="button" class="btn btn-primary" onclick="chiudiAllarmeTerapieGlobali()" style="background:#16a34a; border:none; padding:9px 22px; border-radius:12px; font-weight:800; font-size:13px; color:#ffffff; cursor:pointer; box-shadow:0 3px 10px rgba(22,163,74,0.3);">
              ✓ Chiudi Schermata
            </button>
          </div>
        </div>
      `;
    }
  }

  if (modalAllarme) modalAllarme.classList.add('active');
}
window.apriAllarmiTerapieManuale = apriAllarmiTerapieManuale;

function aggiornaStickyPatientBar() {
  const p = getActivePaziente();
  if (!p) return;
  const elAvatar = document.querySelector('.sticky-patient-avatar');
  const elName = document.getElementById('sticky-patient-name');
  const elSub = document.getElementById('sticky-patient-sub');
  const elAlertPill = document.getElementById('sticky-patient-alert-pill');
  const elAlertCount = document.getElementById('sticky-patient-alert-count');

  const avInfo = getDettagliAvatarPaziente(p);
  if (elAvatar) elAvatar.textContent = avInfo.emoji;

  const eta = calcolaAnniDaData(p.dataNascita);
  const dataNascitaFmt = (typeof formattaDataNascitaItaliana === 'function') ? formattaDataNascitaItaliana(p.dataNascita) : '';
  const annoNascita = (p.dataNascita && p.dataNascita.includes('-')) ? p.dataNascita.split('-')[0] : ((dataNascitaFmt && dataNascitaFmt.includes('/')) ? dataNascitaFmt.split('/')[2] : '');
  const pulitoNome = (p.nome || '').replace(/\s*\(\d+\s*anni\)/gi, '').trim();

  if (elName) elName.textContent = pulitoNome;
  if (elSub) {
    const stanza = p.stanza ? `Stanza ${p.stanza} • ` : 'Domiciliare • ';
    const annoStr = annoNascita ? ` • Anno ${annoNascita}` : '';
    elSub.textContent = `${eta} anni${annoStr} (${dataNascitaFmt}) • ${avInfo.simboloGenere} ${stanza}Cartella Attiva`;
  }

  document.querySelectorAll('.badge-paziente-contestuale').forEach(el => {
    el.innerHTML = `${avInfo.emoji} <span>Paziente: <b>${pulitoNome}</b> (${eta}a)</span>`;
  });

  if (elAlertPill && elAlertCount) {
    const ritardiAttivi = (p.terapie || []).filter(t => isTerapiaPrevistaOggi(t) && !t.fattoOggi && !t.saltatoOggi && verificaStatoOrarioFarmaco(t.ora).inRitardo);
    if (ritardiAttivi.length > 0) {
      elAlertCount.textContent = ritardiAttivi.length;
      elAlertPill.style.display = 'inline-flex';
    } else {
      elAlertPill.style.display = 'none';
    }
  }
}

// Toggle Diagnosi Espandibili su Mobile
window.toggleTuttePatologie = function (btn) {
  const container = btn.closest('.patologie-container');
  if (!container) return;
  const isExp = container.classList.toggle('expanded');
  const allCount = container.querySelectorAll('.patologia-pill').length;
  btn.textContent = isExp ? '▲ Riduci' : `+ Mostra tutte (${allCount})`;
};

// Gestione Mostra/Nascondi Intelligente Barra Sticky Paziente allo Scroll (Anti-duplicazione)
(function initStickyPatientBarScroll() {
  if (window._stickyPatientScrollInit) return;
  window._stickyPatientScrollInit = true;

  function handleStickyScroll() {
    const bar = document.getElementById('sticky-patient-bar');
    if (!bar) return;
    const sy = window.scrollY || document.documentElement.scrollTop || document.body.scrollTop || 0;
    if (sy > 55) {
      if (typeof aggiornaStickyPatientBar === 'function') aggiornaStickyPatientBar();
      bar.classList.add('is-sticky-active');
    } else {
      bar.classList.remove('is-sticky-active');
    }
  }

  window.addEventListener('scroll', handleStickyScroll, { passive: true });
  document.addEventListener('scroll', handleStickyScroll, { passive: true, capture: true });
})();

function apriSwitchPazienteRapido() {
  const modal = document.getElementById('modal-switch-paziente-rapido');
  const container = document.getElementById('lista-switch-pazienti-rapido');
  if (!modal || !container) return;

  const lista = typeof getPazientiAccessibili === 'function' ? getPazientiAccessibili() : (AppData ? AppData.pazienti : []);
  const activeId = AppData ? AppData.activePazienteId : null;

  container.innerHTML = lista.map(p => {
    const isAttivo = (p.id === activeId);
    const eta = calcolaAnniDaData(p.dataNascita);
    const pulitoNome = (p.nome || '').replace(/\s*\(\d+\s*anni\)/gi, '').trim();
    const ritardi = (p.terapie || []).filter(t => isTerapiaPrevistaOggi(t) && !t.fattoOggi && !t.saltatoOggi && verificaStatoOrarioFarmaco(t.ora).inRitardo).length;

    // Avatar and clinical focus by patient
    const avInfo = typeof getDettagliAvatarPaziente === 'function' ? getDettagliAvatarPaziente(p) : null;
    const isFem = (p.sesso === 'F') || (avInfo && avInfo.isFemmina);
    let avatarEmoji = isFem ? (eta >= 65 ? '👵' : '👩') : (eta >= 65 ? '👴' : '👨');
    let avatarBg = isFem ? 'linear-gradient(135deg, #fdf2f8 0%, #fbcfe8 100%)' : 'linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%)';
    let avatarBorder = isFem ? '#f472b6' : '#7dd3fc';
    let focusClinico = p.allettato ? '🛏️ Allettato • Assistenza Continua' : '🚶 Deambulante • Monitoraggio Terapie';

    if (p.id === 'paz_aldo' || pulitoNome.toLowerCase().includes('aldo')) {
      avatarEmoji = '👴';
      avatarBg = 'linear-gradient(135deg, #e0e7ff 0%, #c7d2fe 100%)';
      avatarBorder = '#818cf8';
      focusClinico = '🛏️ Allettato • Epilessia & Post-Ictus (ADI)';
    } else if (p.id === 'paz_angela' || pulitoNome.toLowerCase().includes('angela')) {
      avatarEmoji = '👵';
      avatarBg = 'linear-gradient(135deg, #fce7f3 0%, #fbcfe8 100%)';
      avatarBorder = '#f472b6';
      focusClinico = '🚶 Deambulante • Cardiopatia & Ipertensione';
    } else if (p.id === 'paz_rosa' || pulitoNome.toLowerCase().includes('rosa')) {
      avatarEmoji = '👵';
      avatarBg = 'linear-gradient(135deg, #fae8ff 0%, #f5d0fe 100%)';
      avatarBorder = '#c084fc';
      focusClinico = '🚶 Deambulante • Diabete Tipo 2 & Glicemie';
    } else if (p.id === 'paz_1793216119572' || pulitoNome.toLowerCase().includes('ciro')) {
      avatarEmoji = '👨';
      avatarBg = 'linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%)';
      avatarBorder = '#38bdf8';
      focusClinico = '🚶 Deambulante • Epatite HBV & Lab. Scotti / Policlinico';
    } else if (p.id === 'paz_mariacarmela' || (pulitoNome.toLowerCase().includes('carmela') && pulitoNome.toLowerCase().includes('stoppelli'))) {
      avatarEmoji = '👩';
      avatarBg = 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)';
      avatarBorder = '#f59e0b';
      focusClinico = '🚶 Deambulante • Follow-up Benessere & Nutrizione';
    }

    return `
      <div onclick="selezionaPazienteRapido('${p.id}')" style="display:flex; justify-content:space-between; align-items:center; padding:12px 14px; border-radius:14px; cursor:pointer; transition:all 0.2s cubic-bezier(0.16,1,0.3,1); border:2px solid ${isAttivo ? '#0284c7' : '#e2e8f0'}; background:${isAttivo ? 'linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%)' : '#ffffff'}; box-shadow:${isAttivo ? '0 4px 14px rgba(2,132,199,0.25)' : '0 1px 3px rgba(0,0,0,0.04)'};" onmouseover="this.style.transform='translateY(-2px)';" onmouseout="this.style.transform='translateY(0)';">
        <div style="display:flex; align-items:center; gap:12px;">
          <div style="width:46px; height:46px; border-radius:12px; background:${avatarBg}; border:1.5px solid ${avatarBorder}; display:flex; align-items:center; justify-content:center; font-size:24px; box-shadow:0 2px 6px rgba(0,0,0,0.08); flex-shrink:0;">
            ${avatarEmoji}
          </div>
          <div>
            <div style="font-size:15px; font-weight:800; color:${isAttivo ? '#0369a1' : '#0f172a'}; display:flex; align-items:center; gap:6px;">
              <span>${pulitoNome}</span>
              <span style="font-size:11px; font-weight:700; color:#64748b; background:rgba(0,0,0,0.05); padding:1px 6px; border-radius:6px;">${eta} anni</span>
            </div>
            <div style="font-size:11.5px; color:${isAttivo ? '#0284c7' : '#64748b'}; font-weight:600; margin-top:2px;">${focusClinico}</div>
          </div>
        </div>
        <div style="display:flex; align-items:center; gap:8px;">
          ${ritardi > 0 ? `<span class="badge" style="background:#dc2626; color:#fff; font-size:11px; font-weight:800; padding:4px 8px; border-radius:12px; box-shadow:0 2px 6px rgba(220,38,38,0.3);">🚨 ${ritardi} Ritardi</span>` : ''}
          ${isAttivo
        ? `<span style="font-size:12px; font-weight:800; color:#ffffff; background:linear-gradient(135deg, #0284c7 0%, #0369a1 100%); padding:5px 12px; border-radius:20px; box-shadow:0 2px 6px rgba(2,132,199,0.35);">✓ In Uso</span>`
        : `<span style="font-size:12px; font-weight:700; color:#0369a1; background:#f0f9ff; border:1px solid #bae6fd; padding:5px 12px; border-radius:20px;">Apri Cartella ➔</span>`
      }
        </div>
      </div>
    `;
  }).join('');

  modal.classList.add('active');
  modal.style.display = 'flex';
  document.body.classList.add('modal-open');
}
window.apriSwitchPazienteRapido = apriSwitchPazienteRapido;
window.selezionaPazienteRapido = selezionaPazienteRapido;

function selezionaPazienteRapido(pazienteId) {
  closeModal('modal-switch-paziente-rapido');
  if (pazienteId !== AppData.activePazienteId) {
    cambiaPaziente(pazienteId);
    showToast('Cartella assistito caricata con successo! 👤');
  }
  // Se l'assistito ha ritardi, porta l'operatore subito alla riga lampeggiante
  const p = (AppData.pazienti || []).find(it => it.id === pazienteId);
  if (p && p.terapie) {
    const tRitardo = p.terapie.find(t => isTerapiaPrevistaOggi(t) && !t.fattoOggi && !t.saltatoOggi && verificaStatoOrarioFarmaco(t.ora).inRitardo);
    if (tRitardo) {
      var tabBtn = document.querySelector('[data-target="tab-farmaci"]');
      if (tabBtn) tabBtn.click();
      evidenziaEScrollaAFarmaco(tRitardo.id);
    }
  }
}

// ==========================================================================
// NOTIFICHE PUSH SMARTPHONE & SBLOCCO AUDIO AUTOMATICO
// ==========================================================================
let ultimoNotificaRitardoTimestamp = 0;

function abilitaNotificheEAudioSmartphone() {
  const ctx = getAudioContext();
  if (ctx && ctx.state === 'suspended') {
    ctx.resume();
  }

  if ('vibrate' in navigator) {
    try { navigator.vibrate([200, 100, 200]); } catch (e) { }
  }

  suonaSegnaleDolce();

  if ('Notification' in window) {
    Notification.requestPermission().then(permission => {
      if (permission === 'granted') {
        showToast('Notifiche e Audio attivati su Smartphone! 🔔📲', 'success');
        try {
          new Notification('CareAssist Pro: Allarmi Attivi', {
            body: 'Le notifiche e gli avvisi di terapia sono stati configurati correttamente!',
            icon: 'careassist_icon.jpg'
          });
        } catch (e) { }
      } else {
        showToast('Audio sbloccato. Notifiche di sistema non autorizzate nel browser.', 'info');
      }
    });
  } else {
    showToast('Audio sbloccato con successo! 🔔', 'success');
  }
}
window.abilitaNotificheEAudioSmartphone = abilitaNotificheEAudioSmartphone;

function sbloccaAudioSilenziosoAlPrimoGesto() {
  try {
    const ctx = getAudioContext();
    if (ctx && ctx.state === 'suspended') {
      ctx.resume();
    }
  } catch (e) { }
}
window.addEventListener('click', sbloccaAudioSilenziosoAlPrimoGesto, { once: true, passive: true });
window.addEventListener('touchstart', sbloccaAudioSilenziosoAlPrimoGesto, { once: true, passive: true });


function vaiATerapiaInRitardoAttiva() {
  const p = getActivePaziente();
  if (!p) return;
  const tRitardo = (p.terapie || []).find(t => isTerapiaPrevistaOggi(t) && !t.fattoOggi && !t.saltatoOggi && verificaStatoOrarioFarmaco(t.ora).inRitardo);
  var tabBtn = document.querySelector('[data-target="tab-farmaci"]');
  if (tabBtn) tabBtn.click();
  evidenziaEScrollaAFarmaco(tRitardo ? tRitardo.id : null);
}


