    'STATUS:CONFIRMED',
    'BEGIN:VALARM',
    'TRIGGER:-P7D',
    'ACTION:DISPLAY',
    'DESCRIPTION:Promemoria tra 7 giorni: Prelievo HBV-DNA al Policlinico (T-15gg prima della visita)',
    'END:VALARM',
    'BEGIN:VALARM',
