window.apriPianoTerapeuticoPDF = function (pazienteId) {
  let p = null;
  if (pazienteId && window.pazienti && Array.isArray(window.pazienti)) {
    p = window.pazienti.find(x => x.id === pazienteId);
  }
  if (!p && typeof getActivePaziente === 'function') {
    p = getActivePaziente();
  }
  if (!p && window.pazienti && window.pazienti.length > 0) {
    p = window.pazienti[0];
  }

  if (!p) {
    if (typeof showToast === 'function') {
      showToast('Nessun assistito selezionato per la generazione del Piano Terapeutico.', 'error');
    } else {
      alert('Nessun assistito selezionato.');
    }
    return;
  }

  window._pazientePianoTerapeuticoCorrente = p;

  const headerPazienteEl = document.getElementById('pt-modal-header-paziente');
  if (headerPazienteEl) {
    headerPazienteEl.textContent = p.nome;
  }

  const container = document.getElementById('foglio-a4-piano-terapeutico-content');
  if (container) {
    container.innerHTML = window.generaHtmlPianoTerapeutico(p);
  }

  const modal = document.getElementById('modal-anteprima-piano-terapeutico');
  if (modal) {
    modal.style.display = 'flex';
  }

  if (typeof showToast === 'function') {
    showToast(`Piano Terapeutico e Scorte generati per ${p.nome}.`, 'success');
  }
};

window.chiudiPianoTerapeuticoPDF = function () {
  const modal = document.getElementById('modal-anteprima-piano-terapeutico');
  if (modal) {
    modal.style.display = 'none';
  }
  document.body.classList.remove('printing-piano-terapeutico');
};

window.stampaDirettaPianoTerapeutico = function () {
  document.body.classList.add('printing-piano-terapeutico');
  setTimeout(() => {
    window.print();
    setTimeout(() => {
      document.body.classList.remove('printing-piano-terapeutico');
    }, 1500);
  }, 150);
};

window.condividiPianoTerapeuticoWhatsApp = function () {
  const p = window._pazientePianoTerapeuticoCorrente || (typeof getActivePaziente === 'function' ? getActivePaziente() : null);
  if (!p) return;

  const terapie = (p.terapie || []).slice().sort((a, b) => (a.ora || '99:99').localeCompare(b.ora || '99:99'));
  let msg = `📋 *PIANO TERAPEUTICO, SCORTE & CALENDARIO RICHIESTE RICETTE*\n`;
  msg += `👤 *Assistito:* ${p.nome}\n`;
  msg += `📍 *Indirizzo:* ${p.indirizzo || 'Domicilio'}\n`;
  msg += `👨‍⚕️ *Medico Curante:* ${p.medicoCurante || p.medico || 'Dott. Curante'}\n`;
  msg += `🏥 *Farmacia di Riferimento:* ${p.farmaciaDiRiferimento || p.farmacia || 'Farmacia Territoriale'}\n`;
  if (p.allergie) {
    msg += `⚠️ *Allergie:* ${Array.isArray(p.allergie) ? p.allergie.join(', ') : p.allergie}\n`;
  }
  msg += `\n*CRONOPROGRAMMA SOMMINISTRAZIONI & SCORTE:*\n`;

  if (terapie.length === 0) {
    msg += `Nessuna terapia registrata.\n`;
  } else {
    terapie.forEach(t => {
      const nomeF = t.farmaco || t.nome || t.nomeFarmaco || 'Farmaco';
      const dos = t.dosaggio || t.dose || '1 dose';
      const princ = t.principio || t.principioAttivo || '';
      const sos = (t.alBisogno || t.sos) ? ' [SOS]' : '';
      const salvavita = (t.salvavita || t.critico || t.is112 || nomeF.toLowerCase().includes('salvavita')) ? ' 🚨 [SALVAVITA]' : '';
      const info = window._calcolaDatiScortaERichiesta(t, terapie);

      msg += `⏰ *${t.ora || '--:--'}* - *${nomeF}*${salvavita}${sos}\n`;
      msg += `   • Dose: ${dos}${princ ? ' (Principio: ' + princ + ')' : ''}\n`;
      msg += `   • 📦 Scorta residua: ${info.scortaNum} ${info.unita} (~${info.ggAutonomia} gg di autonomia)\n`;
      msg += `   • 📅 Data prevista richiesta ricetta MMG: *${info.dataRichiestaStr}* (Fine scorta: ${info.dataFineStr})\n`;
      if (t.modo || t.note || t.istruzioni) msg += `   • Istruzioni: ${t.modo || t.note || t.istruzioni}\n`;
      msg += `\n`;
    });
  }

  msg += `_Generato tramite CareAssist Pro_ 🩺`;

  const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(msg)}`;
  window.open(url, '_blank');
};

window.condividiPianoTerapeuticoEmail = function () {
  const p = window._pazientePianoTerapeuticoCorrente || (typeof getActivePaziente === 'function' ? getActivePaziente() : null);
  if (!p) return;

  const terapie = (p.terapie || []).slice().sort((a, b) => (a.ora || '99:99').localeCompare(b.ora || '99:99'));
  const subject = `Piano Terapeutico, Scorte e Calendario Richiesta Ricette - ${p.nome}`;
  let body = `PIANO TERAPEUTICO FARMACOLOGICO, SCORTE & DATE RICHIESTA RICETTE\n`;
  body += `Assistito: ${p.nome}\n`;
  body += `Data: ${new Date().toLocaleDateString('it-IT')}\n`;
  body += `Medico Curante: ${p.medicoCurante || p.medico || 'Dott. Curante'}\n`;
  body += `Farmacia di Riferimento: ${p.farmaciaDiRiferimento || p.farmacia || 'Farmacia Territoriale'}\n\n`;
  body += `DETTAGLIO SOMMINISTRAZIONI, SCORTE E RICHIESTE MMG:\n`;
  terapie.forEach(t => {
    const nomeF = t.farmaco || t.nome || t.nomeFarmaco || 'Farmaco';
    const dos = t.dosaggio || t.dose || '1 dose';
    const info = window._calcolaDatiScortaERichiesta(t, terapie);
    body += `- Ore ${t.ora || '--:--'}: ${nomeF} | Dose: ${dos}\n`;
    body += `  Scorta: ${info.scortaNum} ${info.unita} (~${info.ggAutonomia} gg) | Data prevista richiesta: ${info.dataRichiestaStr} (Fine: ${info.dataFineStr})\n`;
    body += `  Note: ${t.modo || t.note || t.istruzioni || ''}\n\n`;
  });
  body += `Distinti saluti,\nEquipe Territoriale CareAssist Pro`;

  const mailtoUrl = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  window.location.href = mailtoUrl;
};

// ==========================================================================
// 1. DETTATURA VOCALE NOTA DI TURNO & PARSING AUTOMATICO
// ==========================================================================
let _dettaturaNotaRecognition = null;
let _isDettandoNota = false;

function toggleDettaturaVocaleNota() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    showToast('Il riconoscimento vocale non è supportato dal browser corrente.', 'warning');
    return;
  }

  const btn = document.getElementById('btn-mic-dettatura-nota');
  const txtArea = document.getElementById('nota-turno-testo');

  if (_isDettandoNota) {
    if (_dettaturaNotaRecognition) _dettaturaNotaRecognition.stop();
    _isDettandoNota = false;
    if (btn) {
      btn.style.background = '#f0f9ff';
      btn.style.borderColor = '#0284c7';
      btn.style.color = '#0284c7';
      btn.innerHTML = '<span>🎤</span> Dettatura Vocale';
    }
    return;
  }

  try {
    _dettaturaNotaRecognition = new SpeechRecognition();
    _dettaturaNotaRecognition.lang = 'it-IT';
    _dettaturaNotaRecognition.continuous = true;
    _dettaturaNotaRecognition.interimResults = false;

    _dettaturaNotaRecognition.onstart = function () {
      _isDettandoNota = true;
      if (btn) {
        btn.style.background = '#dc2626';
        btn.style.borderColor = '#b91c1c';
        btn.style.color = '#ffffff';
        btn.innerHTML = '<span>⏹️</span> In ascolto... Parla ora!';
      }
      showToast('🎙️ Parla chiaramente: trascrizione in tempo reale...');
    };

    _dettaturaNotaRecognition.onresult = function (event) {
      for (let i = event.resultIndex; i < event.results.length; ++i) {
        if (event.results[i].isFinal) {
          const trascritto = event.results[i][0].transcript.trim();
          if (txtArea) {
            const current = txtArea.value.trim();
            txtArea.value = current ? current + '. ' + trascritto : trascritto;

            // Smart Parsing: Se rileva parole chiave cliniche come alvo, pressione, glicemia o acqua, suggerisce o compila
            if (trascritto.toLowerCase().includes('pressione') || trascritto.toLowerCase().includes('alvo') || trascritto.toLowerCase().includes('beve')) {
              showToast('💡 Rilevati parametri clinici nel parlato!', 'success');
            }
          }
        }
      }
    };

    _dettaturaNotaRecognition.onerror = function (err) {
      console.warn('Speech error:', err);
      _isDettandoNota = false;
      if (btn) {
        btn.style.background = '#f0f9ff';
        btn.style.borderColor = '#0284c7';
        btn.style.color = '#0284c7';
        btn.innerHTML = '<span>🎤</span> Dettatura Vocale';
      }
    };

    _dettaturaNotaRecognition.onend = function () {
      _isDettandoNota = false;
      if (btn) {
        btn.style.background = '#f0f9ff';
        btn.style.borderColor = '#0284c7';
        btn.style.color = '#0284c7';
        btn.innerHTML = '<span>🎤</span> Dettatura Vocale';
      }
    };

    _dettaturaNotaRecognition.start();
  } catch (err) {
    console.error('Impossibile avviare SpeechRecognition:', err);
    showToast('Errore microfono. Verifica i permessi del browser.', 'warning');
  }
}
window.toggleDettaturaVocaleNota = toggleDettaturaVocaleNota;

